1	#ifndef AMR_DISPATCHER_CORE__PLANNING__MAP_GEOMETRY_UTILS_HPP_
2	#define AMR_DISPATCHER_CORE__PLANNING__MAP_GEOMETRY_UTILS_HPP_
3	
4	#include <cstdint>
5	#include <vector>
6	
7	namespace amr_dispatcher_core::planning {
8	
9	// 栅格占用语义（与 nav_msgs/OccupancyGrid 一致）：
10	//   -1 未知 / 0 空闲 / 100 占用。下游 SafetySpaceFilter 将未知与占用统一按不可通行处理。
11	inline constexpr int8_t kCellUnknown = -1;
12	inline constexpr int8_t kCellFree = 0;
13	inline constexpr int8_t kCellOccupied = 100;
14	
15	// 栅格地图纯数据结构（零 ROS 依赖）。
16	// data 为行主序（index = row * width + col），长度应为 width * height。
17	struct MapGrid {
18	  uint32_t width = 0;    // 列数（像素）
19	  uint32_t height = 0;   // 行数（像素）
