678	// ---- StationCatalogReloader：mtime 轮询热重载，校验失败保留旧目录 ----
679	StationCatalogReloader::StationCatalogReloader(std::filesystem::path path)
680	    : path_(std::move(path)),
681	      watcher_(path_.string(), [this](const YAML::Node&) { TryLoad(true); }) {
682	  TryLoad(false);   // 初始加载等价节点 on_configure 的一次性读取
683	  watcher_.Tick();  // 建立 mtime 基线：首拍只记基线不回调，之后的变化才重载
684	}
685	
686	bool StationCatalogReloader::Tick() {
687	  const auto before = reload_count_;
688	  watcher_.Tick();
689	  if (!watcher_.last_error().empty()) {
690	    last_error_ = watcher_.last_error();  // YAML 解析失败：回调未触发，旧目录保持
691	  }
692	  if (!loaded_) {
693	    // C1 闭环兜底：构造时文件缺失（use_map_server 场景下 dispatcher 先于
694	    // map_ingest 启动）时，HotReloadWatcher 对"文件首次出现"只记 mtime 基线、
695	    // 不触发重载回调——首次成功拍永远不会补加载。这里在未加载状态下重试
696	    // 初始加载，保证晚生成的目录（map_ingest 写出的 generated/stations.yaml）
697	    // 一旦出现即可被调度侧接管（成功即计一次换新，返回 true 驱动调用方同步）。
698	    TryLoad(true);
699	  }
700	  return reload_count_ > before;
701	}
702	
703	std::string StationCatalogReloader::last_error() const {
704	  return last_error_;
705	}
706	
707	void StationCatalogReloader::TryLoad(bool count_as_reload) {
708	  if (auto loaded = LoadStationCatalog(path_)) {
709	    catalog_ = std::move(*loaded);
710	    loaded_ = true;
711	    if (count_as_reload) {
712	      ++reload_count_;
713	    }
714	    last_error_.clear();
715	  } else {
716	    // 校验失败（空目录、重复 id、非法位姿等）：保留旧目录，记录错误
717	    last_error_ = "station catalog invalid or unreadable: " + path_.string();
718	  }
719	}
