15	namespace amr_dispatcher_core::planning {
16	namespace {
17	
18	// 8 邻域方向（顺时针，自正北起）：与 skeleton_extractor 保持一致。
19	constexpr int kDRow[8] = {-1, -1, 0, 1, 1, 1, 0, -1};
20	constexpr int kDCol[8] = {0, 1, 1, 1, 0, -1, -1, -1};
21	
22	// 像素坐标（整数栅格）。
23	struct Pixel {
24	  int col = 0;
25	  int row = 0;
26	
27	  bool operator==(const Pixel& other) const {
28	    return col == other.col && row == other.row;
29	  }
30	};
31	
32	struct PixelHash {
33	  size_t operator()(const Pixel& p) const {
34	    return (static_cast<size_t>(static_cast<uint32_t>(p.col)) << 32) ^
35	           static_cast<size_t>(static_cast<uint32_t>(p.row));
36	  }
37	};
38	
39	// 8 邻域环上的连通组数（P2..P9,P2 环状序列中 0→1 跳变次数）：
40	//   0 = 孤立，1 = 端点，2 = 中段，>= 3 = 分叉。
41	// 与 skeleton_extractor.cpp 中 CrossingNumber 完全相同的判据。
42	int CrossingNumber(const BinaryGrid& grid, int col, int row) {
43	  int neighbors[8];
44	  int B = 0;
45	  for (int i = 0; i < 8; ++i) {
46	    neighbors[i] = grid.GetValue(col + kDCol[i], row + kDRow[i]) ? 1 : 0;
47	    B += neighbors[i];
48	  }
49	  if (B == 0) {
50	    return 0;
51	  }
52	  if (B == 8) {
53	    return 1;
54	  }
55	  int groups = 0;
56	  for (int i = 0; i < 8; ++i) {
57	    if (!neighbors[i] && neighbors[(i + 1) % 8]) {
58	      ++groups;
59	    }
60	  }
61	  return groups;
62	}
63	
64	// 折线累加长度：相邻折线点间欧氏距离之和。
65	double PolylineLength(const std::vector<std::pair<double, double>>& polyline) {
66	  double total = 0.0;
67	  for (size_t i = 1; i < polyline.size(); ++i) {
68	    const double dx = polyline[i].first - polyline[i - 1].first;
69	    const double dy = polyline[i].second - polyline[i - 1].second;
70	    total += std::hypot(dx, dy);
71	  }
72	  return total;
73	}
74	
75	// 点 P 到线段 AB 的最近点（垂足或端点）。
76	// 返回 (proj_x, proj_y, dist, t)，t 在 [0,1] 表示投影参数位置。
77	std::pair<std::pair<double, double>, double> ProjectPointToSegment(
78	    double px, double py, double ax, double ay, double bx, double by,
79	    double* t_out) {
80	  const double abx = bx - ax;
81	  const double aby = by - ay;
82	  const double apx = px - ax;
83	  const double apy = py - ay;
84	  const double ab_len_sq = abx * abx + aby * aby;
85	  double t = 0.0;
86	  if (ab_len_sq > 0.0) {
87	    t = (apx * abx + apy * aby) / ab_len_sq;
88	    t = std::max(0.0, std::min(1.0, t));
89	  }
90	  const double qx = ax + t * abx;
91	  const double qy = ay + t * aby;
92	  const double dist = std::hypot(px - qx, py - qy);
93	  if (t_out != nullptr) {
94	    *t_out = t;
95	  }
96	  return {{qx, qy}, dist};
97	}
98	
99	// ---- 骨架图追踪 -------------------------------------------------------------
100	
101	// 内部图边（像素域）：from/to 为节点像素，polyline_px 为从 from 到 to 的
102	// 像素序列（含两端节点）。在生成 CatalogStationEdge 时再统一转世界坐标。
103	struct PixelEdge {
104	  Pixel from;
105	  Pixel to;
106	  std::vector<Pixel> polyline_px;
107	};
108	
109	// 提取所有骨架特征点（crossing != 2 的像素）。返回特征点集合。
110	std::vector<Pixel> ExtractFeaturePixels(const BinaryGrid& skeleton) {
111	  std::vector<Pixel> features;
112	  for (uint32_t row = 0; row < skeleton.height; ++row) {
113	    for (uint32_t col = 0; col < skeleton.width; ++col) {
114	      const int c = static_cast<int>(col);
115	      const int r = static_cast<int>(row);
116	      if (!skeleton.GetValue(c, r)) {
117	        continue;
118	      }
119	      const int crossings = CrossingNumber(skeleton, c, r);
120	      if (crossings != 2) {
121	        features.push_back({c, r});
122	      }
123	    }
124	  }
125	  return features;
126	}
127	
128	// 单步推进：从 prev -> cur，返回所有可能的下一像素（除 prev 之外的骨架
129	// 邻居）。返回的下一像素若仍是中段（crossing==2）需要继续推进。
130	std::vector<Pixel> NextPixels(const BinaryGrid& skeleton, const Pixel& prev,
131	                              const Pixel& cur) {
132	  std::vector<Pixel> next;
133	  for (int i = 0; i < 8; ++i) {
134	    const Pixel nb{cur.col + kDCol[i], cur.row + kDRow[i]};
135	    if (nb == prev) {
136	      continue;
137	    }
138	    if (skeleton.GetValue(nb.col, nb.row)) {
139	      next.push_back(nb);
140	    }
141	  }
142	  return next;
143	}
144	
145	// 在多候选下一像素中选择主续像素：
146	//   1. 优先选不在当前链中的像素（避免回环自相交）；
147	//   2. 其中选与来向 (cur - prev) 点积最大者（直线延续优先于斜向逃逸）。
148	// 这处理 1 像素宽骨架在 8 邻域下的"环上相邻"情况：L 形拐角内侧像素
149	// 会有 3 个骨架邻居（prev、内侧对角、正前方），ring 连通组仍为 2，
150	// 必须靠方向选择走出拐角而不是误判为分叉。
151	Pixel PickNextPixel(const Pixel& prev, const Pixel& cur,
152	                    const std::vector<Pixel>& nexts,
153	                    const std::unordered_set<Pixel, PixelHash>& chain_set) {
154	  const int dir_col = cur.col - prev.col;
155	  const int dir_row = cur.row - prev.row;
156	  Pixel best{-1, -1};
157	  double best_cos = -std::numeric_limits<double>::infinity();
158	  bool best_fresh = false;
159	  for (const Pixel& nb : nexts) {
160	    const bool fresh = chain_set.count(nb) == 0;
161	    const int step_col = nb.col - cur.col;
162	    const int step_row = nb.row - cur.row;
163	    const double step_len =
164	        (step_col == 0 || step_row == 0) ? 1.0 : std::sqrt(2.0);
165	    const double cos_angle =
166	        (dir_col * step_col + dir_row * step_row) / step_len;
167	    // 未访问优先；并列时按方向余弦。
168	    if (best.col == -1 || (fresh && !best_fresh) ||
169	        (fresh == best_fresh && cos_angle > best_cos)) {
170	      best = nb;
171	      best_cos = cos_angle;
172	      best_fresh = fresh;
173	    }
174	  }
175	  return best;
176	}
177	
178	// 从起点 start 沿邻居 first_step 方向追踪，直到抵达下一个特征点。
179	// 返回包含 start、所有中间像素、终止特征点的完整链。
180	// 若 first_step 本身即特征点，则链长为 2。
181	// 若链成环回到起点（无其他特征点），返回空——由外层做闭合环处理。
182	std::vector<Pixel> TraceFromToFeature(
183	    const BinaryGrid& skeleton, const Pixel& start, const Pixel& first_step,
184	    const std::unordered_set<Pixel, PixelHash>& feature_set) {
185	  std::vector<Pixel> chain;
186	  chain.push_back(start);
187	  chain.push_back(first_step);
188	  std::unordered_set<Pixel, PixelHash> chain_set;
189	  chain_set.insert(start);
190	  chain_set.insert(first_step);
191	
192	  Pixel prev = start;
193	  Pixel cur = first_step;
194	  const size_t max_steps =
195	      static_cast<size_t>(skeleton.width) * skeleton.height + 1;
196	  while (chain.size() <= max_steps) {
197	    // 当前点若是特征点（且不是起点本身），停止。
198	    if (!(cur == start) && feature_set.count(cur) > 0) {
199	      return chain;
200	    }
201	    // 中段：在非 prev 邻居中挑选主续方向（避免 8 邻域内侧角点误判分叉）。
202	    const std::vector<Pixel> nexts = NextPixels(skeleton, prev, cur);
203	    if (nexts.empty()) {
204	      return chain;  // 死胡同
205	    }
206	    const Pixel next = PickNextPixel(prev, cur, nexts, chain_set);
207	    if (next.col == -1) {
208	      return chain;
209	    }
210	    prev = cur;
211	    cur = next;
212	    chain.push_back(cur);
213	    chain_set.insert(cur);
214	    // 闭合回到起点：返回当前链（标记为环）
215	    if (cur == start) {
216	      return chain;
217	    }
218	  }
219	  return chain;
220	}
221	
222	// ---- 投影与边拆分 -----------------------------------------------------------
223	
224	// 在 edge.polyline（世界坐标）上找点 (px,py) 的最近投影点。
225	// 返回 (proj_x, proj_y, distance, segment_index, segment_t)
226	struct ProjectionResult {
227	  double px = 0.0;
228	  double py = 0.0;
229	  double distance = std::numeric_limits<double>::infinity();
230	  size_t segment_index = 0;  // 所在折线段索引（[i, i+1]）
231	  double segment_t = 0.0;    // 段内参数 [0,1]
232	};
233	
234	ProjectionResult ProjectToPolyline(
235	    double px, double py,
236	    const std::vector<std::pair<double, double>>& polyline) {
237	  ProjectionResult best;
238	  if (polyline.size() < 2) {
239	    return best;
240	  }
241	  for (size_t i = 0; i + 1 < polyline.size(); ++i) {
242	    double t = 0.0;
243	    const auto& a = polyline[i];
244	    const auto& b = polyline[i + 1];
245	    const auto proj = ProjectPointToSegment(px, py, a.first, a.second, b.first,
246	                                            b.second, &t);
247	    if (proj.second < best.distance) {
248	      best.px = proj.first.first;
249	      best.py = proj.first.second;
250	      best.distance = proj.second;
251	      best.segment_index = i;
252	      best.segment_t = t;
253	    }
254	  }
255	  return best;
256	}
257	
258	}  // namespace
259	
260	TopologyBuildResult BuildTopologyCatalog(
261	    const BinaryGrid& skeleton, const MapGrid& map_info,
262	    const std::vector<AnchorStation>& anchors,
263	    const TopologyBuilderConfig& config) {
264	  TopologyBuildResult result;
265	  catalog::StationCatalog& catalog = result.catalog;
266	  catalog.map_hash = config.map_hash;
267	  catalog.graph_version = config.graph_version;
268	
269	  if (skeleton.width == 0 || skeleton.height == 0) {
270	    result.error_message = "skeleton is empty";
271	    return result;
272	  }
273	
274	  // ---- 第一步：提取特征点并分配 RoadNode id ----
275	  const std::vector<Pixel> feature_pixels = ExtractFeaturePixels(skeleton);
276	  std::unordered_set<Pixel, PixelHash> feature_set(feature_pixels.begin(),
277	                                                   feature_pixels.end());
278	
279	  // 像素 -> RoadNode id 映射
280	  std::unordered_map<Pixel, std::string, PixelHash> pixel_to_node_id;
281	  std::unordered_map<Pixel, size_t, PixelHash> pixel_to_node_index;
282	  int next_node_idx = 0;
283	  for (const Pixel& p : feature_pixels) {
284	    const WorldCoord w =
285	        PixelToWorld(PixelCoord{static_cast<double>(p.col),
286	                                static_cast<double>(p.row)},
287	                     map_info);
288	    catalog::RoadNode node;
289	    node.id = "rn_" + std::to_string(p.col) + "_" + std::to_string(p.row);
290	    node.x = w.x;
291	    node.y = w.y;
292	    catalog.road_nodes.push_back(node);
293	    pixel_to_node_id[p] = node.id;
294	    pixel_to_node_index[p] = catalog.road_nodes.size() - 1;
295	    (void)next_node_idx;
296	    ++next_node_idx;
297	  }
298	
299	  // ---- 第二步：从每个特征点的每个邻居方向追踪，提取像素边 ----
300	  // visited_directed_edge：(from_node, first_step_pixel) 标记该方向是否已追踪。
301	  // 同一条无向边 (A,m1,...,B) 会被两端各追踪一次，用 (from_node, first_step)
302	  // 去重——注意反向追踪时 first_step 是该边在 B 端的最后中间像素，与正向
303	  // 的 first_step 不同，因此需要额外检查边是否已存在。
304	  std::vector<PixelEdge> pixel_edges;
305	  std::unordered_set<Pixel, PixelHash> visited_middle;
306	
307	  for (const Pixel& start : feature_pixels) {
308	    // 收集起点的所有骨架邻居
309	    std::vector<Pixel> neighbors;
310	    for (int i = 0; i < 8; ++i) {
311	      const Pixel nb{start.col + kDCol[i], start.row + kDRow[i]};
312	      if (skeleton.GetValue(nb.col, nb.row)) {
313	        neighbors.push_back(nb);
314	      }
315	    }
316	    for (const Pixel& first_step : neighbors) {
317	      // 若 first_step 已被访问且不是特征点，说明该方向上的边已被处理
318	      // （来自对端或同端的另一个起点方向）。
319	      if (feature_set.count(first_step) == 0 &&
320	          visited_middle.count(first_step) > 0) {
321	        continue;
322	      }
323	      // 检查边是否已被反向追踪（first_step 的对端像素对应）。
324	      // 简单做法：直接追踪，事后通过 (from_id,to_id,polyline) 三元组去重。
325	      std::vector<Pixel> chain =
326	          TraceFromToFeature(skeleton, start, first_step, feature_set);
327	      if (chain.size() < 2) {
328	        continue;
329	      }
330	      // 标记中间像素为已访问（特征点除外）。
331	      for (size_t i = 1; i + 1 < chain.size(); ++i) {
332	        visited_middle.insert(chain[i]);
333	      }
334	      PixelEdge pe;
335	      pe.from = chain.front();
336	      pe.to = chain.back();
337	      pe.polyline_px = chain;
338	      pixel_edges.push_back(std::move(pe));
339	    }
340	  }
341	
342	  // 处理孤立闭合环：未被任何边覆盖的骨架像素（无任何特征点的纯环）。
343	  // 遍历所有骨架像素，若某像素既不在 visited_middle 也不是 feature，则
344	  // 说明它属于某个未被追踪的闭合环。在环上任取一点作为 RoadNode，并把
345	  // 整条环像素序列作为一条"自环"边（from=to=该节点）——但 stations.yaml
346	  // schema 不允许 from==to，改为在环上任取两个像素作为 RoadNode，环切成
347	  // 两段边。
348	  {
349	    std::unordered_set<Pixel, PixelHash> covered;
350	    for (const PixelEdge& e : pixel_edges) {
351	      for (const Pixel& p : e.polyline_px) {
352	        covered.insert(p);
353	      }
354	    }
355	    // 收集所有未被覆盖的骨架像素
356	    std::vector<Pixel> orphan;
357	    for (uint32_t row = 0; row < skeleton.height; ++row) {
358	      for (uint32_t col = 0; col < skeleton.width; ++col) {
359	        const Pixel p{static_cast<int>(col), static_cast<int>(row)};
360	        if (skeleton.GetValue(p.col, p.row) && covered.count(p) == 0) {
361	          orphan.push_back(p);
362	        }
363	      }
364	    }
365	    // BFS 分组各连通环
366	    std::unordered_set<Pixel, PixelHash> visited_orphan;
367	    for (const Pixel& seed : orphan) {
368	      if (visited_orphan.count(seed) > 0) {
369	        continue;
370	      }
371	      // BFS 收集本环所有像素
372	      std::vector<Pixel> ring;
373	      std::queue<Pixel> bfs;
374	      bfs.push(seed);
375	      visited_orphan.insert(seed);
376	      while (!bfs.empty()) {
377	        const Pixel cur = bfs.front();
378	        bfs.pop();
379	        ring.push_back(cur);
380	        for (int i = 0; i < 8; ++i) {
381	          const Pixel nb{cur.col + kDCol[i], cur.row + kDRow[i]};
382	          if (!skeleton.GetValue(nb.col, nb.row) ||
383	              visited_orphan.count(nb) > 0 ||
384	              feature_set.count(nb) > 0) {
385	            continue;
386	          }
387	          visited_orphan.insert(nb);
388	          bfs.push(nb);
389	        }
390	      }
391	      if (ring.size() < 3) {
392	        continue;  // 过短环不应出现，防御性跳过
393	      }
394	      // 在环上任取两个像素作为 RoadNode，环切成两段。
395	      // 简化：取 ring[0] 与 ring[ring.size()/2]。
396	      const Pixel n_a = ring.front();
397	      const Pixel n_b = ring[ring.size() / 2];
398	      auto add_node = [&](const Pixel& p) {
399	        if (pixel_to_node_id.count(p) > 0) {
400	          return;
401	        }
402	        const WorldCoord w =
403	            PixelToWorld(PixelCoord{static_cast<double>(p.col),
404	                                    static_cast<double>(p.row)},
405	                         map_info);
406	        catalog::RoadNode node;
407	        node.id = "rn_" + std::to_string(p.col) + "_" + std::to_string(p.row);
408	        node.x = w.x;
409	        node.y = w.y;
410	        catalog.road_nodes.push_back(node);
411	        pixel_to_node_id[p] = node.id;
412	        feature_set.insert(p);
413	      };
414	      add_node(n_a);
415	      add_node(n_b);
416	      // 在环上从 n_a 沿两个方向追踪到 n_b。每个方向用“已访问集 + 方向延续”
417	      // 选择下一像素：优先未访问像素并按来向方向余弦择优（复用 PickNextPixel），
418	      // 避免旧实现按环上枚举顺序取“最后一个邻居”导致在拐角处来回震荡、
419	      // 纯环（crossing 恒为 2）始终无法走到 n_b 的问题。
420	      auto trace_on_ring = [&](const Pixel& from, const Pixel& first,
421	                               const Pixel& target) {
422	        std::vector<Pixel> path{from, first};
423	        std::unordered_set<Pixel, PixelHash> visited;
424	        visited.insert(from);
425	        visited.insert(first);
426	        Pixel prev = from;
427	        Pixel cur = first;
428	        const size_t limit = ring.size() + 8;
429	        while (!(cur == target) && path.size() <= limit) {
430	          // 收集环内非 prev 邻居作为候选。
431	          std::vector<Pixel> candidates;
432	          for (int i = 0; i < 8; ++i) {
433	            const Pixel nb{cur.col + kDCol[i], cur.row + kDRow[i]};
434	            if (nb == prev) {
435	              continue;
436	            }
437	            if (!skeleton.GetValue(nb.col, nb.row)) {
438	              continue;
439	            }
440	            if (std::find(ring.begin(), ring.end(), nb) == ring.end()) {
441	              continue;
442	            }
443	            candidates.push_back(nb);
444	          }
445	          if (candidates.empty()) {
446	            break;
447	          }
448	          // 未访问优先 + 方向延续（不折返），拐角处的对角“捷径”仅在同为
449	          // 未访问时依方向余弦落败于正向像素。
450	          const Pixel next = PickNextPixel(prev, cur, candidates, visited);
451	          if (next.col == -1) {
452	            break;
453	          }
454	          visited.insert(next);
455	          prev = cur;
456	          cur = next;
457	          path.push_back(cur);
458	        }
459	        return path;
460	      };
461	      // n_a 的两个环邻居
462	      std::vector<Pixel> a_nbrs;
463	      for (int i = 0; i < 8; ++i) {
464	        const Pixel nb{n_a.col + kDCol[i], n_a.row + kDRow[i]};
465	        if (skeleton.GetValue(nb.col, nb.row) &&
466	            std::find(ring.begin(), ring.end(), nb) != ring.end() &&
467	            !(nb == n_b)) {
468	          a_nbrs.push_back(nb);
469	        }
470	      }
471	      for (const Pixel& first : a_nbrs) {
472	        const std::vector<Pixel> path = trace_on_ring(n_a, first, n_b);
473	        if (path.size() >= 2 && path.back() == n_b) {
474	          PixelEdge pe;
475	          pe.from = n_a;
476	          pe.to = n_b;
477	          pe.polyline_px = path;
478	          pixel_edges.push_back(std::move(pe));
479	        }
480	      }
481	    }
482	  }
483	
484	  // 边去重：同向边需折线逐点相等才算重复；反向边需折线反向逐点相等。
485	  // 不能仅按 (from, to, polyline_size) 判重——纯环切出的两条半环边端点相同、
486	  // 长度也可能相同，但折线不同，必须作为平行边同时保留。
487	  {
488	    std::vector<PixelEdge> unique_edges;
489	    for (const auto& e : pixel_edges) {
490	      bool dup = false;
491	      for (const auto& u : unique_edges) {
492	        if (e.from == u.from && e.to == u.to &&
493	            e.polyline_px == u.polyline_px) {
494	          dup = true;
495	          break;
496	        }
497	        // 反向同边（A->B 与 B->A）：折线反向逐点相等才是同一条几何链。
498	        if (e.from == u.to && e.to == u.from &&
499	            e.polyline_px.size() == u.polyline_px.size() &&
500	            std::equal(e.polyline_px.begin(), e.polyline_px.end(),
501	                       u.polyline_px.rbegin())) {
502	          dup = true;
503	          break;
504	        }
505	      }
506	      if (!dup) {
507	        unique_edges.push_back(e);
508	      }
509	    }
510	    pixel_edges = std::move(unique_edges);
511	  }
512	
513	  // ---- 第三步：转换为 CatalogStationEdge（世界坐标 polyline + 累加距离）----
514	  for (const PixelEdge& pe : pixel_edges) {
515	    const auto it_from = pixel_to_node_id.find(pe.from);
516	    const auto it_to = pixel_to_node_id.find(pe.to);
517	    if (it_from == pixel_to_node_id.end() || it_to == pixel_to_node_id.end()) {
518	      continue;  // 防御：未注册的端点跳过
519	    }
520	    catalog::CatalogStationEdge edge;
521	    edge.from = it_from->second;
522	    edge.to = it_to->second;
523	    edge.bidirectional = true;
524	    edge.enabled = true;
525	    edge.polyline.reserve(pe.polyline_px.size());
526	    for (const Pixel& p : pe.polyline_px) {
527	      const WorldCoord w =
528	          PixelToWorld(PixelCoord{static_cast<double>(p.col),
529	                                  static_cast<double>(p.row)},
530	                       map_info);
531	      edge.polyline.emplace_back(w.x, w.y);
532	    }
533	    edge.distance_m = PolylineLength(edge.polyline);
534	    catalog.edges.push_back(std::move(edge));
535	  }
536	
537	  // ---- 第四步：站点吸附与边拆分 ----
538	  for (const AnchorStation& anchor : anchors) {
539	    if (catalog.edges.empty()) {
540	      result.error_message =
541	          "no edges available to snap station " + anchor.id;
542	      return result;
543	    }
544	    // 找到最近边及其投影点
545	    size_t best_edge_idx = std::numeric_limits<size_t>::max();
546	    ProjectionResult best_proj;
547	    for (size_t i = 0; i < catalog.edges.size(); ++i) {
548	      const auto& edge = catalog.edges[i];
549	      const ProjectionResult proj =
550	          ProjectToPolyline(anchor.x, anchor.y, edge.polyline);
551	      if (proj.distance < best_proj.distance) {
552	        best_proj = proj;
553	        best_edge_idx = i;
554	      }
555	    }
556	    if (best_edge_idx == std::numeric_limits<size_t>::max()) {
557	      result.error_message = "no valid edge for station " + anchor.id;
558	      return result;
559	    }
560	    if (best_proj.distance > config.max_snap_dist_m) {
561	      std::ostringstream oss;
562	      oss << "Station " << anchor.id
563	          << " is too far from skeleton: " << best_proj.distance << "m";
564	      result.error_message = oss.str();
565	      return result;
566	    }
567	    // I2：检测与已放置站点重合的吸附点。若不检查，第二个重合锚点会把
568	    // 第一个站点的边全部重定向到自身，导致第一个站点孤立、连通性校验
569	    // 报 "disconnected" 且错误信息无法指向根因。这里给出明确诊断。
570	    for (const auto& st_existing : catalog.stations) {
571	      if (std::hypot(st_existing.x - best_proj.px,
572	                     st_existing.y - best_proj.py) < 1e-6) {
573	        std::ostringstream oss;
574	        oss << "Station " << anchor.id << " coincides with station "
575	            << st_existing.id << " at (" << best_proj.px << ", "
576	            << best_proj.py << "); coincident anchors are not supported";
577	        result.error_message = oss.str();
578	        return result;
579	      }
580	    }
581	
582	    // 将站点作为图节点（id = anchor.id，世界坐标采用投影点使节点落在
583	    // 骨架上——这样 SkeletonPlanner 沿折线循迹时能精确到站点）。
584	    catalog::Station st;
585	    st.id = anchor.id;
586	    st.type = anchor.type;
587	    st.x = best_proj.px;
588	    st.y = best_proj.py;
589	    st.yaw = anchor.yaw;
590	    catalog.stations.push_back(st);
591	
592	    // 拆分最近边：U -> V 变 U -> anchor -> V
593	    catalog::CatalogStationEdge original =
594	        catalog.edges[best_edge_idx];
595	    // 构造两段 polyline
596	    std::vector<std::pair<double, double>> poly_a;  // U -> proj
597	    std::vector<std::pair<double, double>> poly_b;  // proj -> V
598	    const size_t seg = best_proj.segment_index;
599	    const std::pair<double, double> proj_pt{best_proj.px, best_proj.py};
600	    // poly_a: polyline[0..seg] + proj_pt
601	    for (size_t i = 0; i <= seg; ++i) {
602	      poly_a.push_back(original.polyline[i]);
603	    }
604	    // 若 proj_pt 与末端点不同则补上（t<1 时需要）
605	    if (best_proj.segment_t < 1.0 - 1e-9 ||
606	        poly_a.back() != proj_pt) {
607	      if (std::hypot(poly_a.back().first - proj_pt.first,
608	                     poly_a.back().second - proj_pt.second) > 1e-9) {
609	        poly_a.push_back(proj_pt);
610	      }
611	    }
612	    // poly_b: proj_pt + polyline[seg+1..end]
613	    poly_b.push_back(proj_pt);
614	    for (size_t i = seg + 1; i < original.polyline.size(); ++i) {
615	      poly_b.push_back(original.polyline[i]);
616	    }
617	    // 清理 poly_b 起点：若 proj_pt 恰等于 polyline[seg+1] 则跳过重复
618	    if (poly_b.size() >= 2 &&
619	        std::hypot(poly_b[0].first - poly_b[1].first,
620	                   poly_b[0].second - poly_b[1].second) < 1e-9) {
621	      poly_b.erase(poly_b.begin());
622	    }
623	
624	    // 移除原边，加入两段新边
625	    catalog.edges.erase(catalog.edges.begin() +
626	                        static_cast<long>(best_edge_idx));
627	    if (poly_a.size() >= 2) {
628	      catalog::CatalogStationEdge e1;
629	      e1.from = original.from;
630	      e1.to = anchor.id;
631	      e1.bidirectional = original.bidirectional;
632	      e1.enabled = original.enabled;
633	      e1.polyline = std::move(poly_a);
634	      e1.distance_m = PolylineLength(e1.polyline);
635	      catalog.edges.push_back(std::move(e1));
636	    } else {
637	      // 投影点恰是端点 U：站点直接替代 U，但 schema 要求 from!=to。
638	      // 防御：跳过该段（意味着 anchor 与 U 重合，anchor 站点应替代 U
639	      // 的节点身份——但我们已将 anchor 作为新站点，需要至少保留 anchor
640	      // 的接入）。
641	      // 此时若 poly_b 也不存在，则 anchor 成为孤立站点，连通性校验会失败。
642	      // 为容错，把 U 节点的所有其他边重定向到 anchor。
643	      for (auto& e : catalog.edges) {
644	        if (e.from == original.from) e.from = anchor.id;
645	        if (e.to == original.from) e.to = anchor.id;
646	      }
647	    }
648	    if (poly_b.size() >= 2) {
649	      catalog::CatalogStationEdge e2;
650	      e2.from = anchor.id;
651	      e2.to = original.to;
652	      e2.bidirectional = original.bidirectional;
653	      e2.enabled = original.enabled;
654	      e2.polyline = std::move(poly_b);
655	      e2.distance_m = PolylineLength(e2.polyline);
656	      catalog.edges.push_back(std::move(e2));
657	    } else {
658	      // 投影点恰是端点 V：同上重定向。
659	      for (auto& e : catalog.edges) {
660	        if (e.from == original.to) e.from = anchor.id;
661	        if (e.to == original.to) e.to = anchor.id;
662	      }
663	    }
664	  }
665	
666	  // ---- 第五步：连通性校验 ----
667	  if (catalog.stations.size() >= 2) {
668	    const std::string& base = catalog.stations[0].id;
669	    for (size_t i = 1; i < catalog.stations.size(); ++i) {
670	      const std::string& target = catalog.stations[i].id;
671	      const auto path = catalog::FindRoutePath(catalog, base, target);
672	      if (!path.has_value()) {
673	        result.error_message =
674	            "Map network is disconnected: station " + target +
675	            " cannot reach " + base;
676	        return result;
677	      }
678	    }
679	  }
680	
681	  // ---- 第六步：schema 校验 ----
682	  std::string validation_error;
683	  if (!catalog::ValidateStationCatalog(catalog, &validation_error)) {
684	    result.error_message =
685	        "generated catalog failed validation: " + validation_error;
686	    return result;
687	  }
688	
689	  result.success = true;
690	  return result;
691	}
692	
693	}  // namespace amr_dispatcher_core::planning
