1	#include "amr_dispatcher_core/dispatcher/traffic_reservation.hpp"
2	
3	#include <algorithm>
4	#include <sstream>
5	#include <unordered_set>
6	
7	namespace amr_dispatcher_core::dispatcher {
8	namespace {
9	
10	bool StartsWith(const std::string& value, const std::string& prefix) {
11	  return value.rfind(prefix, 0) == 0;
12	}
13	
14	constexpr const char* kBlockPrefix = "traffic_block:";
15	
16	// A7：剪除已过期的时空预约（end < now），防止历史条目在表中无限累积
17	void PruneExpiredTimeSpace(
18	    std::unordered_map<std::string, std::vector<TimeSpaceReservation>>& reservations,
19	    const std::chrono::steady_clock::time_point now) {
20	  for (auto it = reservations.begin(); it != reservations.end();) {
21	    auto& list = it->second;
22	    list.erase(std::remove_if(list.begin(), list.end(),
23	                              [now](const TimeSpaceReservation& reservation) {
24	                                return reservation.interval.end < now;
25	                              }),
26	               list.end());
27	    if (list.empty()) {
28	      it = reservations.erase(it);
29	    } else {
30	      ++it;
31	    }
32	  }
33	}
34	
35	}  // namespace
36	
37	std::string ResourceTable::RouteEdgeId(const std::string& from, const std::string& to) {
38	  return from <= to ? "route_edge:" + from + "__" + to : "route_edge:" + to + "__" + from;
39	}
40	
41	std::string ResourceTable::RouteNodeId(const std::string& station_id) {
42	  return "route_node:" + station_id;
43	}
44	
45	std::optional<std::pair<std::string, std::string>> ResourceTable::ParseRouteEdge(
46	    const std::string& resource_id) {
47	  const std::string prefix = "route_edge:";
48	  if (!StartsWith(resource_id, prefix)) {
49	    return std::nullopt;
50	  }
51	  const auto separator = resource_id.find("__", prefix.size());
52	  if (separator == std::string::npos) {
53	    return std::nullopt;
54	  }
55	  const auto first = resource_id.substr(prefix.size(), separator - prefix.size());
56	  const auto second = resource_id.substr(separator + 2);
57	  if (first.empty() || second.empty()) {
58	    return std::nullopt;
59	  }
60	  return std::make_pair(first, second);
61	}
62	
63	bool ResourceTable::IsTrafficBlockOwner(const std::string& owner_id) {
64	  return StartsWith(owner_id, kBlockPrefix);
65	}
66	
67	std::vector<std::string> ResourceTable::BuildLockIds(
68	    const std::vector<std::string>& station_path, const bool include_intersection_locks) {
69	  std::vector<std::string> lock_ids;
70	  std::unordered_set<std::string> seen;  // 保序去重：重复节点/边只保留首次出现
71	  const auto append_once = [&lock_ids, &seen](const std::string& lock_id) {
72	    if (seen.insert(lock_id).second) {
73	      lock_ids.push_back(lock_id);
74	    }
75	  };
76	  if (include_intersection_locks) {
77	    for (const auto& station_id : station_path) {
78	      append_once(RouteNodeId(station_id));
79	    }
80	  }
81	  for (std::size_t index = 1; index < station_path.size(); ++index) {
82	    append_once(RouteEdgeId(station_path[index - 1], station_path[index]));
83	  }
84	  return lock_ids;
85	}
86	
87	ResourceTable::ReserveResult ResourceTable::Reserve(
88	    const std::string& mission_id, const std::vector<std::string>& resource_ids) {
89	  ReserveResult result;
90	  if (mission_id.empty()) {
91	    result.message = "mission id must not be empty";
92	    return result;
93	  }
94	  // A7：入口先剪除过期时空预约，表大小不随历史条目累积
95	  PruneExpiredTimeSpace(time_space_reservations_, std::chrono::steady_clock::now());
96	  for (const auto& resource_id : resource_ids) {
97	    const auto existing = locks_.find(resource_id);
98	    if (existing != locks_.end() && existing->second != mission_id) {
99	      std::ostringstream oss;
100	      oss << "resource locked: " << resource_id << " by " << existing->second;
101	      result.message = oss.str();
102	      return result;  // 未落任何锁，原子性成立
103	    }
104	  }
105	  // A7：写入前过滤同任务已持有锁与列表内重复，newly_reserved 只记真正新增
106	  std::unordered_set<std::string> counted;
107	  for (const auto& resource_id : resource_ids) {
108	    if (!counted.insert(resource_id).second) {
109	      continue;  // 列表内重复不重复计入
110	    }
111	    const auto existing = locks_.find(resource_id);
112	    if (existing != locks_.end() && existing->second == mission_id) {
113	      continue;  // 同任务已持有，不算新增
114	    }
115	    locks_[resource_id] = mission_id;
116	    result.newly_reserved.push_back(resource_id);
117	  }
118	  std::ostringstream oss;
119	  oss << "reserved " << result.newly_reserved.size() << " resource(s)";
120	  result.success = true;
121	  result.message = oss.str();
122	  return result;
123	}
124	
125	bool ResourceTable::ReserveTimeSpace(
126	    const std::string& mission_id,
127	    const std::string& resource_id,
128	    std::chrono::steady_clock::time_point start,
129	    std::chrono::steady_clock::time_point end,
130	    std::string* message) {
131	  if (start >= end) {
132	    if (message) *message = "invalid time interval: start >= end";
133	    return false;
134	  }
135	
136	  // M3：入口先剪除过期时空预约，与 Reserve/Release 保持一致——
137	  // 否则已结束的时段仍会参与冲突判断，误拒时间重叠的回溯候选。
138	  PruneExpiredTimeSpace(time_space_reservations_, std::chrono::steady_clock::now());
139	
140	  // 1. 检查是否存在永久排他锁（人工封路等）
141	  if (Locked(resource_id) && Owner(resource_id) != mission_id) {
142	    if (message) *message = "resource statically locked by: " + *Owner(resource_id);
143	    return false;
144	  }
145	
146	  // 2. 检查该资源在目标时间区间内是否与其他任务的预约时段重叠
147	  TimeInterval candidate_interval{start, end};
148	  auto& reservations = time_space_reservations_[resource_id];
149	  for (const auto& res : reservations) {
150	    if (res.mission_id != mission_id && res.interval.OverlapsWith(candidate_interval)) {
151	      if (message) {
152	        *message = "time-space contention on " + resource_id + " with " + res.mission_id;
153	      }
154	      return false;
155	    }
156	  }
157	
158	  // 3. 无时空冲突，落入预约表
159	  reservations.push_back(TimeSpaceReservation{mission_id, resource_id, candidate_interval});
160	  if (message) *message = "time-space reservation confirmed";
161	  return true;
162	}
163	
164	ResourceTable::ReleaseResult ResourceTable::Release(const std::string& mission_id) {
165	  ReleaseResult result;
166	  // A7：入口先剪除过期时空预约
167	  PruneExpiredTimeSpace(time_space_reservations_, std::chrono::steady_clock::now());
168	  for (auto lock = locks_.begin(); lock != locks_.end();) {
169	    if (lock->second == mission_id) {
170	      lock = locks_.erase(lock);
171	      result.released = true;
172	    } else {
173	      ++lock;
174	    }
175	  }
176	
177	  // 清空该任务的所有时空预约
178	  for (auto& [res_id, list] : time_space_reservations_) {
179	    auto before_size = list.size();
180	    list.erase(std::remove_if(list.begin(), list.end(),
181	                              [&mission_id](const TimeSpaceReservation& r) {
182	                                return r.mission_id == mission_id;
183	                              }),
184	               list.end());
185	    if (list.size() < before_size) {
186	      result.released = true;
187	    }
188	  }
189	
190	  result.message =
191	      result.released ? "released resources of " + mission_id : "no resources held by " + mission_id;
192	  return result;
193	}
