195	bool ResourceTable::Block(const std::string& resource_id, const std::string& reason,
196	                          std::string* message) {
197	  const std::string owner = std::string(kBlockPrefix) + reason;
198	  const auto existing = locks_.find(resource_id);
199	  if (existing != locks_.end()) {
200	    if (message != nullptr) {
201	      *message = "resource already held: " + resource_id + " by " + existing->second;
202	    }
203	    return false;
204	  }
205	  locks_[resource_id] = owner;
206	  if (message != nullptr) {
207	    *message = "blocked " + resource_id;
