221	    if (message != nullptr) {
222	      *message = "cannot unblock resource held by mission: " + existing->second;
223	    }
224	    return false;
225	  }
226	  locks_.erase(existing);
227	  if (message != nullptr) {
228	    *message = "unblocked " + resource_id;
229	  }
230	  return true;
