233	std::string MapIngestNode::SerializeCatalog(const StationCatalog& catalog) {
234	  // 与 LoadStationCatalog 的逐行严格解析 schema 对齐（Task 1）：
235	  // version(map_hash/graph_version) -> stations -> road_nodes -> edges(polyline)。
236	  std::ostringstream out;
237	  out << "version:\n";
238	  out << "  map_hash: " << Quote(catalog.map_hash) << "\n";
239	  out << "  graph_version: " << Quote(catalog.graph_version) << "\n";
240	
241	  out << "stations:\n";
242	  for (const auto& station : catalog.stations) {
243	    out << "  - id: " << Quote(station.id) << "\n";
244	    out << "    x: " << FormatDouble(station.x) << "\n";
245	    out << "    y: " << FormatDouble(station.y) << "\n";
246	    out << "    yaw: " << FormatDouble(station.yaw) << "\n";
247	    out << "    type: " << Quote(station.type) << "\n";
248	  }
249	
250	  out << "road_nodes:\n";
251	  for (const auto& node : catalog.road_nodes) {
252	    out << "  - id: " << Quote(node.id) << "\n";
253	    out << "    x: " << FormatDouble(node.x) << "\n";
254	    out << "    y: " << FormatDouble(node.y) << "\n";
255	    out << "    yaw: " << FormatDouble(node.yaw) << "\n";
256	  }
257	
258	  out << "edges:\n";
259	  for (const auto& edge : catalog.edges) {
260	    out << "  - from: " << Quote(edge.from) << "\n";
261	    out << "    to: " << Quote(edge.to) << "\n";
262	    out << "    distance_m: " << FormatDouble(edge.distance_m) << "\n";
263	    out << "    bidirectional: " << (edge.bidirectional ? "true" : "false") << "\n";
264	    out << "    enabled: " << (edge.enabled ? "true" : "false") << "\n";
265	    out << "    polyline:\n";
266	    for (const auto& point : edge.polyline) {
267	      out << "      - [" << FormatDouble(point.first) << ", " << FormatDouble(point.second)
268	          << "]\n";
269	    }
270	  }
271	  return out.str();
272	}
273	
274	bool MapIngestNode::WriteCatalogAtomic(const StationCatalog& catalog) const {
275	  const std::filesystem::path final_path(output_stations_file_);
276	  const std::filesystem::path tmp_path(final_path.string() + ".tmp");
277	  std::error_code ec;
278	
279	  if (final_path.has_parent_path()) {
280	    std::filesystem::create_directories(final_path.parent_path(), ec);
281	    if (ec) {
282	      RCLCPP_ERROR(get_logger(), "Cannot create directory for %s: %s",
283	                   final_path.parent_path().string().c_str(), ec.message().c_str());
284	      return false;
285	    }
286	  }
287	
288	  {
289	    std::ofstream out(tmp_path, std::ios::trunc);
290	    if (!out) {
291	      RCLCPP_ERROR(get_logger(), "Cannot open temp file %s for writing", tmp_path.c_str());
292	      return false;
293	    }
294	    out << SerializeCatalog(catalog);
295	    out.flush();
296	    if (!out) {
297	      out.close();
298	      std::filesystem::remove(tmp_path, ec);
299	      RCLCPP_ERROR(get_logger(), "Failed writing temp file %s", tmp_path.c_str());
300	      return false;
301	    }
302	  }
303	
304	  // 回读校验：tmp 文件必须能被调度侧的严格解析器 LoadStationCatalog 接受，
305	  // 否则删除 tmp、保留旧文件——绝不让半截/坏目录进入热重载路径。
306	  if (!LoadStationCatalog(tmp_path)) {
307	    std::filesystem::remove(tmp_path, ec);
308	    RCLCPP_ERROR(get_logger(),
309	                 "Round-trip validation failed for %s; generated YAML is not parseable "
310	                 "by LoadStationCatalog (keeping existing catalog)",
311	                 tmp_path.c_str());
312	    return false;
313	  }
314	
315	  // 同目录内 rename(2) 为原子操作：调度端要么看到旧文件要么看到新文件。
316	  std::filesystem::rename(tmp_path, final_path, ec);
317	  if (ec) {
318	    std::filesystem::remove(tmp_path, ec);
319	    RCLCPP_ERROR(get_logger(), "Atomic rename %s -> %s failed: %s", tmp_path.c_str(),
320	                 final_path.c_str(), ec.message().c_str());
321	    return false;
322	  }
323	  return true;
324	}
325	
326	void MapIngestNode::MapCallback(const OccupancyGrid::SharedPtr msg) {
327	  if (msg->info.width == 0 || msg->info.height == 0) {
328	    RCLCPP_WARN(get_logger(), "Ignoring invalid map: width=%u height=%u", msg->info.width,
329	                msg->info.height);
330	    return;
331	  }
332	  const std::size_t expected_cells =
333	      static_cast<std::size_t>(msg->info.width) * msg->info.height;
334	  if (msg->data.size() != expected_cells) {
335	    RCLCPP_WARN(get_logger(), "Ignoring malformed map: data size %zu != %u x %u",
336	                msg->data.size(), msg->info.width, msg->info.height);
337	    return;
338	  }
339	
340	  // I2：/map 单发（transient_local）不会重来——缓存消息与内容 hash（I1 含
341	  // origin），本次立即处理；若 markers 未就绪，check_timer_ 之后基于缓存补跑。
342	  last_map_msg_ = msg;
343	  last_map_hash_ = ComputeMapHash(*msg);
344	  ProcessMap();
345	}
346	
347	void MapIngestNode::CheckTimerCallback() {
348	  // 尚未收到 /map，或未配置 markers（anchors 唯一来源）时补跑无意义；
349	  // 是否需要真正重跑统一交由 ProcessMap 内的 ingest_hash 去重裁决：
350	  // 首次未成功（last_ingest_hash_ 为空）必然重试；成功后仅当 markers 被
351	  // 编辑（锚点摘要变化）才会重新生成目录并触发调度侧热重载。
352	  if (!last_map_msg_ || markers_file_.empty()) {
353	    return;
354	  }
355	  ProcessMap();
356	}
357	
358	void MapIngestNode::ProcessMap() {
359	  if (!last_map_msg_ || last_map_hash_.empty()) {
360	    return;
361	  }
362	  const OccupancyGrid& msg = *last_map_msg_;
363	
364	  // ---- ① 加载站点锚点（markers.yaml anchors 段） ----
365	  const std::vector<AnchorStation> anchors = LoadAnchors();
366	  if (anchors.empty()) {
367	    // 节流日志：check_timer_ 每秒重试，等待窗口内不刷屏。
368	    RCLCPP_ERROR_THROTTLE(get_logger(), *get_clock(), 10000,
369	                         "No station anchors available (markers_file: '%s'); waiting for a "
370	                         "valid markers file before generating the catalog",
371	                         markers_file_.c_str());
372	    return;
373	  }
374	
375	  // 同图 + 同锚点重复触发：跳过重写，避免无谓触发调度侧热重载。
376	  const std::string ingest_hash = last_map_hash_ + "#" + ComputeAnchorsDigest(anchors);
377	  if (ingest_hash == last_ingest_hash_) {
378	    RCLCPP_DEBUG(get_logger(), "Map and anchors unchanged (%s); skipping re-ingest",
379	                 last_map_hash_.c_str());
380	    return;
381	  }
382	
383	  // ---- ② OccupancyGrid -> 核心库 MapGrid ----
384	  MapGrid grid;
385	  grid.width = msg.info.width;
386	  grid.height = msg.info.height;
387	  grid.resolution = msg.info.resolution;
388	  grid.origin_x = msg.info.origin.position.x;
389	  grid.origin_y = msg.info.origin.position.y;
390	  grid.origin_yaw = amr_dispatcher_core::path_tracking::YawFromQuaternion(
391	      msg.info.origin.orientation.z, msg.info.origin.orientation.w);
392	  grid.data.assign(msg.data.begin(), msg.data.end());
393	
394	  // ---- ③ 核心库算法流水线 ----
395	  SafetyFilterConfig safety_cfg;
396	  safety_cfg.robot_radius_m = robot_radius_m_;
397	  safety_cfg.safety_margin_m = safety_margin_m_;
398	
399	  PruneConfig prune_cfg;
400	  prune_cfg.min_branch_length_m = min_branch_length_m_;
401	  prune_cfg.resolution = grid.resolution;
402	
403	  TopologyBuilderConfig builder_cfg;
404	  builder_cfg.max_snap_dist_m = max_snap_dist_m_;
405	  builder_cfg.map_hash = last_map_hash_;
406	  builder_cfg.graph_version = "v1";
407	
408	  const BinaryGrid safety_grid = amr_dispatcher_core::planning::FilterSafetySpace(grid, safety_cfg);
409	  const BinaryGrid skeleton = amr_dispatcher_core::planning::ZhangSuenThinning(safety_grid);
410	
411	  std::vector<PixelCoord> protected_points;
412	  protected_points.reserve(anchors.size());
413	  for (const auto& anchor : anchors) {
414	    protected_points.push_back(
415	        amr_dispatcher_core::planning::WorldToPixel(WorldCoord{anchor.x, anchor.y}, grid));
416	  }
417	  const BinaryGrid pruned =
418	      amr_dispatcher_core::planning::PruneSkeletonProtected(skeleton, protected_points, prune_cfg);
419	
420	  // ---- ④ 拓扑构建与站点吸附 ----
421	  const auto result = amr_dispatcher_core::planning::BuildTopologyCatalog(pruned, grid, anchors,
422	                                                                          builder_cfg);
423	  if (!result.success) {
424	    // 节流：失败由 check_timer_ 每秒重试（last_ingest_hash_ 仍为空），不刷屏。
425	    RCLCPP_ERROR_THROTTLE(get_logger(), *get_clock(), 10000,
426	                         "Map ingest failed: %s (keeping existing catalog; will retry)",
427	                         result.error_message.c_str());
428	    return;
429	  }
430	
431	  // ---- ⑤ 原子写出 + RViz Marker ----
432	  if (!WriteCatalogAtomic(result.catalog)) {
433	    RCLCPP_ERROR_THROTTLE(get_logger(), *get_clock(), 10000,
434	                         "Failed to write catalog to '%s' (keeping existing catalog; will retry)",
435	                         output_stations_file_.c_str());
436	    return;
437	  }
438	  last_ingest_hash_ = ingest_hash;
439	  if (!msg.header.frame_id.empty()) {
440	    map_frame_id_ = msg.header.frame_id;
441	  }
442	
443	  RCLCPP_INFO(get_logger(),
444	              "Successfully ingested map and generated %s (%zu stations, %zu road nodes, "
445	              "%zu edges) [map_hash=%s]",
446	              output_stations_file_.c_str(), result.catalog.stations.size(),
447	              result.catalog.road_nodes.size(), result.catalog.edges.size(),
448	              last_map_hash_.c_str());
449	
450	  if (publish_markers_) {
451	    PublishTopologyMarkers(result.catalog);
452	  }
453	}
454	
455	void MapIngestNode::PublishTopologyMarkers(const StationCatalog& catalog) {
456	  visualization_msgs::msg::MarkerArray array;
457	  const auto stamp = now();
458	
459	  // 先 DELETEALL 清残影：重新导入（地图更新）时上一批 Marker 全部作废。
460	  visualization_msgs::msg::Marker clear;
461	  clear.header.frame_id = map_frame_id_;
462	  clear.header.stamp = stamp;
463	  clear.ns = "topology_reset";
464	  clear.id = 0;
465	  clear.action = visualization_msgs::msg::Marker::DELETEALL;
466	  array.markers.push_back(clear);
467	
468	  int id = 0;
469	  const auto base_marker = [&](const std::string& ns, int type) {
470	    visualization_msgs::msg::Marker marker;
471	    marker.header.frame_id = map_frame_id_;
472	    marker.header.stamp = stamp;
473	    marker.ns = ns;
474	    marker.id = id++;
475	    marker.type = type;
476	    marker.action = visualization_msgs::msg::Marker::ADD;
477	    marker.pose.orientation.w = 1.0;
478	    // 永久驻留（lifetime=0）+ transient_local 发布：晚加入的 RViz 也能看到。
479	    return marker;
480	  };
481	
482	  // 端点查找表：折线退化（<2 点）时回退用站点/节点坐标补两个端点。
483	  std::unordered_map<std::string, std::pair<double, double>> endpoint_xy;
484	  for (const auto& node : catalog.road_nodes) {
485	    endpoint_xy[node.id] = {node.x, node.y};
486	    auto marker = base_marker("road_nodes", visualization_msgs::msg::Marker::SPHERE);
487	    marker.pose.position.x = node.x;
488	    marker.pose.position.y = node.y;
489	    marker.pose.position.z = 0.05;
490	    marker.scale.x = 0.15;
491	    marker.scale.y = 0.15;
492	    marker.scale.z = 0.15;
493	    marker.color = Color(0.65f, 0.65f, 0.65f, 0.9f);
494	    array.markers.push_back(marker);
495	  }
496	
497	  for (const auto& station : catalog.stations) {
498	    endpoint_xy[station.id] = {station.x, station.y};
499	    auto marker = base_marker("stations", visualization_msgs::msg::Marker::CYLINDER);
500	    marker.pose.position.x = station.x;
501	    marker.pose.position.y = station.y;
502	    marker.pose.position.z = 0.05;
503	    marker.scale.x = 0.3;
504	    marker.scale.y = 0.3;
505	    marker.scale.z = 0.1;
506	    marker.color = StationColor(station.type);
507	    array.markers.push_back(marker);
508	
509	    auto label = base_marker("station_labels", visualization_msgs::msg::Marker::TEXT_VIEW_FACING);
510	    label.pose.position.x = station.x;
511	    label.pose.position.y = station.y;
512	    label.pose.position.z = 0.5;
513	    label.scale.z = 0.25;
514	    label.color = Color(1.0f, 1.0f, 1.0f, 0.95f);
515	    label.text = station.id;
516	    array.markers.push_back(label);
517	  }
518	
519	  // 边：LINE_STRIP 沿真实 polyline 走廊中心线（而非两点直线）。
520	  for (const auto& edge : catalog.edges) {
521	    auto marker = base_marker("edges", visualization_msgs::msg::Marker::LINE_STRIP);
522	    marker.scale.x = 0.06;  // 线宽（米）
523	    marker.color = Color(0.1f, 0.8f, 0.9f, 0.9f);
524	    if (edge.polyline.size() >= 2) {
525	      marker.points.reserve(edge.polyline.size());
526	      for (const auto& point : edge.polyline) {
527	        geometry_msgs::msg::Point p;
528	        p.x = point.first;
529	        p.y = point.second;
530	        p.z = 0.03;
531	        marker.points.push_back(p);
532	      }
533	    } else {
534	      // 折线缺失的退化边：以两端点连线兜底，保证拓扑关系仍可视化。
535	      const auto from = endpoint_xy.find(edge.from);
536	      const auto to = endpoint_xy.find(edge.to);
537	      if (from == endpoint_xy.end() || to == endpoint_xy.end()) {
538	        continue;
539	      }
540	      geometry_msgs::msg::Point a;
541	      a.x = from->second.first;
542	      a.y = from->second.second;
543	      a.z = 0.03;
544	      geometry_msgs::msg::Point b;
545	      b.x = to->second.first;
546	      b.y = to->second.second;
547	      b.z = 0.03;
548	      marker.points.push_back(a);
549	      marker.points.push_back(b);
550	    }
551	    array.markers.push_back(marker);
552	  }
553	
554	  marker_pub_->publish(array);
555	  RCLCPP_INFO(get_logger(), "Published topology markers: %zu stations, %zu road nodes, "
556	              "%zu edges on %s",
557	              catalog.stations.size(), catalog.road_nodes.size(), catalog.edges.size(),
558	              marker_topic_.c_str());
559	}
560	
561	}  // namespace amr_dispatcher_ros
562	
563	int main(int argc, char** argv) {
564	  rclcpp::init(argc, argv);
565	  rclcpp::spin(std::make_shared<amr_dispatcher_ros::MapIngestNode>());
566	  rclcpp::shutdown();
567	  return 0;
568	}
