111	      "/v2/cancel_queued_mission",
112	      std::bind(&DispatcherNode::CancelQueuedMissionCb, this, std::placeholders::_1, std::placeholders::_2));
113	  preempt_srv_ = create_service<amr_dispatcher_interfaces::srv::PreemptMission>(
114	      "/v2/preempt_mission",
115	      std::bind(&DispatcherNode::PreemptMissionCb, this, std::placeholders::_1, std::placeholders::_2));
116	  reprioritize_srv_ = create_service<amr_dispatcher_interfaces::srv::ReprioritizeQueuedMission>(
117	      "/v2/reprioritize_queued_mission",
118	      std::bind(&DispatcherNode::ReprioritizeQueuedMissionCb, this, std::placeholders::_1, std::placeholders::_2));
119	  estimate_cost_srv_ = create_service<amr_dispatcher_interfaces::srv::EstimateMissionCost>(
120	      "/v2/estimate_mission_cost",
121	      std::bind(&DispatcherNode::EstimateMissionCostCb, this, std::placeholders::_1, std::placeholders::_2));
122	  block_route_srv_ = create_service<amr_dispatcher_interfaces::srv::BlockStationRoute>(
123	      "/v2/block_station_route",
124	      std::bind(&DispatcherNode::BlockStationRouteCb, this, std::placeholders::_1, std::placeholders::_2));
125	  detect_deadlock_srv_ = create_service<amr_dispatcher_interfaces::srv::DetectTrafficDeadlock>(
126	      "/v2/detect_traffic_deadlock",
127	      std::bind(&DispatcherNode::DetectTrafficDeadlockCb, this, std::placeholders::_1, std::placeholders::_2));
128	  list_stations_srv_ = create_service<amr_dispatcher_interfaces::srv::ListStations>(
129	      "/v2/list_stations",
130	      std::bind(&DispatcherNode::ListStationsCb, this, std::placeholders::_1, std::placeholders::_2));
131	  list_reservations_srv_ = create_service<amr_dispatcher_interfaces::srv::ListTrafficReservations>(
132	      "/v2/list_traffic_reservations",
133	      std::bind(&DispatcherNode::ListTrafficReservationsCb, this, std::placeholders::_1, std::placeholders::_2));
134	  reserve_facility_srv_ = create_service<amr_dispatcher_interfaces::srv::ReserveFacilityResource>(
135	      "/v2/reserve_facility_resource",
136	      std::bind(&DispatcherNode::ReserveFacilityResourceCb, this, std::placeholders::_1, std::placeholders::_2));
137	  snapshot_srv_ = create_service<amr_dispatcher_interfaces::srv::GetOperatorSnapshot>(
138	      "/v2/get_operator_snapshot",
139	      std::bind(&DispatcherNode::GetOperatorSnapshotCb, this, std::placeholders::_1, std::placeholders::_2));
140	  validate_site_srv_ = create_service<amr_dispatcher_interfaces::srv::ValidateSiteConfig>(
141	      "/v2/validate_site_config",
142	      std::bind(&DispatcherNode::ValidateSiteConfigCb, this, std::placeholders::_1, std::placeholders::_2));
143	
144	  // 导航后端：默认 plan（行为与既有代码逐字节一致）；action 模式派发改发 NavigateSequence 单点 goal
145	  navigation_backend_ = get_parameter("navigation_backend").as_string();
146	  if (navigation_backend_ != "plan" && navigation_backend_ != "action") {
147	    RCLCPP_WARN(get_logger(), "Unknown navigation_backend '%s', falling back to 'plan'",
148	                navigation_backend_.c_str());
149	    navigation_backend_ = "plan";
150	  }
151	  // ExecuteMission action server：HandleGoal 校验（非空/不重复/资源可预占），
152	  // HandleAccepted 只做入队 + 存 goal handle（不起线程）
153	  execute_action_server_ = rclcpp_action::create_server<ExecuteMission>(
154	      this, "/execute_mission",
155	      std::bind(&DispatcherNode::HandleGoal, this, std::placeholders::_1, std::placeholders::_2),
156	      std::bind(&DispatcherNode::HandleCancel, this, std::placeholders::_1),
157	      std::bind(&DispatcherNode::HandleAccepted, this, std::placeholders::_1));
158	  if (navigation_backend_ == "action") {
159	    nav_client_ = rclcpp_action::create_client<NavigateSequence>(this, "/navigate_sequence");
160	  }
161	
162	  // B6：参数热重载——比较器与三个调度节奏参数允许运行时改写。
163	  // 校验失败返回空 reason（rclcpp 按"拒绝"处理）；comparator 在此预校验，
164	  // 未知值直接拒绝（避免 SetComparator 对未知名静默失败导致实际策略与参数漂移）。
165	  param_callback_handle_ = add_on_set_parameters_callback(
166	      [this](const std::vector<rclcpp::Parameter>& params) {
167	        rcl_interfaces::msg::SetParametersResult result;
168	        result.successful = true;
169	        for (const auto& p : params) {
170	          const std::string& name = p.get_name();
171	          if (name == "comparator") {
172	            const std::string v = p.as_string();
173	            auto comp = amr_dispatcher_core::dispatcher::CreateMissionComparator(v);
174	            if (!comp) {
175	              result.successful = false;
176	              result.reason = "unknown comparator: " + v;
177	              RCLCPP_WARN(get_logger(), "Parameter reload rejected: %s",
178	                          result.reason.c_str());
179	              continue;
180	            }
181	            if (queue_) {
182	              queue_->SetComparator(std::move(comp));
183	            }
184	            RCLCPP_INFO(get_logger(), "Parameter reload: comparator -> %s", v.c_str());
185	          } else if (name == "schedule_rate_hz") {
186	            const double v = p.as_double();
187	            if (v <= 0.0) {
188	              result.successful = false;
189	              result.reason = "schedule_rate_hz must be > 0";
190	              continue;
191	            }
192	            if (schedule_timer_) {
193	              schedule_timer_->reset();
194	              schedule_timer_ = create_wall_timer(
195	                  std::chrono::duration<double>(1.0 / v),
196	                  std::bind(&DispatcherNode::ScheduleTick, this));
197	            }
198	            RCLCPP_INFO(get_logger(), "Parameter reload: schedule_rate_hz -> %.2f", v);
199	          } else if (name == "deadlock_check_rate_hz") {
200	            const double v = p.as_double();
201	            if (v <= 0.0) {
202	              result.successful = false;
203	              result.reason = "deadlock_check_rate_hz must be > 0";
204	              continue;
205	            }
206	            if (deadlock_timer_) {
207	              deadlock_timer_->reset();
208	              deadlock_timer_ = create_wall_timer(
209	                  std::chrono::duration<double>(1.0 / v),
210	                  std::bind(&DispatcherNode::DeadlockTick, this));
211	            }
212	            RCLCPP_INFO(get_logger(), "Parameter reload: deadlock_check_rate_hz -> %.2f", v);
213	          } else if (name == "max_active_missions") {
214	            const int64_t v = p.as_int();
215	            if (v < 1) {
216	              result.successful = false;
217	              result.reason = "max_active_missions must be >= 1";
218	              continue;
219	            }
220	            RCLCPP_INFO(get_logger(), "Parameter reload: max_active_missions -> %lld",
221	                        static_cast<long long>(v));
222	          } else if (name == "planner_type") {
223	            const std::string v = p.as_string();
224	            if (v != "mock" && v != "skeleton") {
225	              result.successful = false;
226	              result.reason = "planner_type must be 'mock' or 'skeleton': " + v;
227	              RCLCPP_WARN(get_logger(), "Parameter reload rejected: %s",
228	                          result.reason.c_str());
229	              continue;
230	            }
231	            planner_type_ = v;
232	            RebuildPlanner();  // 单线程 spin：回调期间无规划请求在途，可安全换实例
233	            RCLCPP_INFO(get_logger(), "Parameter reload: planner_type -> %s", v.c_str());
234	          } else if (name == "expected_map_hash") {
235	            expected_map_hash_ = p.as_string();
236	            RCLCPP_INFO(get_logger(),
237	                        "Parameter reload: expected_map_hash -> %s",
238	                        expected_map_hash_.empty() ? "<disabled>"
239	                                                   : expected_map_hash_.c_str());
240	          }
241	          // 其余已声明参数不回执：rclcpp 仍正常赋值，仅不产生日志噪声
242	        }
243	        return result;
244	      });
245	
246	  RCLCPP_INFO(get_logger(),
247	              "DispatcherNode configured (capacity=%zu, comparator=%s, navigation_backend=%s)",
248	              cap, comp_name.c_str(), navigation_backend_.c_str());
249	  return CallbackReturn::SUCCESS;
250	}
