252	CallbackReturn DispatcherNode::on_activate(const rclcpp_lifecycle::State& /*state*/) {
253	  state_pub_->on_activate();
254	  event_pub_->on_activate();
255	  plan_pub_->on_activate();
256	  topology_pub_->on_activate();
257	
258	  const double sched_hz = get_parameter("schedule_rate_hz").as_double();
259	  schedule_timer_ = create_wall_timer(
260	      std::chrono::duration<double>(1.0 / sched_hz),
261	      std::bind(&DispatcherNode::ScheduleTick, this));
262	
263	  const double deadlock_hz = get_parameter("deadlock_check_rate_hz").as_double();
264	  deadlock_timer_ = create_wall_timer(
265	      std::chrono::duration<double>(1.0 / deadlock_hz),
266	      std::bind(&DispatcherNode::DeadlockTick, this));
267	
268	  state_timer_ = create_wall_timer(500ms, std::bind(&DispatcherNode::PublishState, this));
269	
270	  // 1Hz 驱动站点目录 mtime 热重载（HotReloadWatcher 由调用方驱动）
271	  reload_timer_ = create_wall_timer(1s, [this]() {
272	    if (!catalog_reloader_) return;
273	    if (catalog_reloader_->Tick()) {
274	      RCLCPP_INFO(get_logger(), "Station catalog hot-reloaded: %zu stations",
275	                  catalog_reloader_->catalog().stations.size());
276	      // SkeletonPlanner 持有目录副本：热重载后必须同步，否则仍按旧折线规划
277	      auto* skeleton_planner =
278	          dynamic_cast<amr_dispatcher_core::planning::SkeletonPlanner*>(planner_.get());
279	      if (skeleton_planner != nullptr) {
280	        skeleton_planner->UpdateCatalog(catalog_reloader_->catalog());
281	        RCLCPP_INFO(get_logger(), "SkeletonPlanner catalog synchronized (%zu stations)",
282	                    catalog_reloader_->catalog().stations.size());
283	      }
284	    } else if (!catalog_reloader_->last_error().empty()) {
285	      // 重载失败（YAML 解析或校验不过）：旧目录继续生效，节流告警提示修复文件
286	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
287	                           "Station catalog reload failed, keeping previous: %s",
288	                           catalog_reloader_->last_error().c_str());
289	    }
290	  });
291	
292	  RCLCPP_INFO(get_logger(), "DispatcherNode activated");
293	  return CallbackReturn::SUCCESS;
294	}
