296	void DispatcherNode::RebuildPlanner() {
297	  const double step_size = get_parameter("path_step_size_m").as_double();
298	  if (planner_type_ == "skeleton") {
299	    planner_ = std::make_unique<amr_dispatcher_core::planning::SkeletonPlanner>(
300	        catalog_reloader_ ? catalog_reloader_->catalog()
301	                          : amr_dispatcher_core::catalog::StationCatalog{},
302	        amr_dispatcher_core::planning::SkeletonPlanner::Config{step_size});
303	    RCLCPP_INFO(get_logger(),
304	                "Path planner: SkeletonPlanner (mixed-graph polyline, step %.2f m)",
305	                step_size);
306	    return;
307	  }
308	  if (planner_type_ != "mock") {
309	    RCLCPP_WARN(get_logger(),
310	                "Unknown planner_type '%s', falling back to MockLinearPlanner",
311	                planner_type_.c_str());
312	  }
313	  planner_ = std::make_unique<amr_dispatcher_core::MockLinearPlanner>(step_size);
314	  RCLCPP_INFO(get_logger(), "Path planner: MockLinearPlanner (step %.2f m)", step_size);
315	}
