330	CallbackReturn DispatcherNode::on_cleanup(const rclcpp_lifecycle::State& /*state*/) {
331	  submit_srv_.reset();
332	  cancel_srv_.reset();
333	  pause_srv_.reset();
334	  resume_srv_.reset();
335	  reserve_srv_.reset();
336	  release_srv_.reset();
337	  enqueue_srv_.reset();
338	  cancel_queued_srv_.reset();
339	  preempt_srv_.reset();
340	  reprioritize_srv_.reset();
341	  estimate_cost_srv_.reset();
342	  block_route_srv_.reset();
343	  detect_deadlock_srv_.reset();
344	  list_stations_srv_.reset();
345	  list_reservations_srv_.reset();
346	  reserve_facility_srv_.reset();
347	  snapshot_srv_.reset();
348	  validate_site_srv_.reset();
349	  // B2：clean up 前先逐个收口在途 ExecuteMission goal——
350	  // 不复位的 handle 在 server 销毁后会让 action 客户端永久悬挂；
351	  // 同时释放 HandleGoal 阶段预占的 required_resources 锁。
352	  // rclcpp_action 状态机约束：canceled() 仅 CANCELING、abort() 仅 EXECUTING，
353	  // 其余状态（ACCEPTED 未执行）先 execute() 再 abort()，与 FinishExecuteGoal 同构。
354	  for (auto& [mission_id, handle] : execute_goal_handles_) {
355	    if (!handle) {
356	      continue;
357	    }
358	    if (reservation_table_) {
359	      reservation_table_->Release(mission_id);
360	    }
361	    auto result = std::make_shared<ExecuteMission::Result>();
362	    result->success = false;
363	    result->error_code = 1;
364	    result->message = "dispatcher cleaning up";
365	    try {
366	      if (handle->is_canceling()) {
367	        handle->canceled(result);
368	      } else if (handle->is_executing()) {
369	        handle->abort(result);
370	      } else {
371	        handle->execute();
372	        handle->abort(result);
373	      }
374	    } catch (const std::exception& ex) {
375	      RCLCPP_ERROR(get_logger(), "on_cleanup: finish goal %s failed: %s",
376	                   mission_id.c_str(), ex.what());
377	    }
378	  }
379	  execute_action_server_.reset();
380	  nav_client_.reset();
381	  execute_goal_handles_.clear();
382	  mission_dispatch_start_.clear();
383	  mission_dispatch_time_.clear();
384	  pending_wait_.clear();
385	  mission_reserved_at_.clear();
386	  pending_nav_mission_id_.clear();
387	  pending_nav_goal_handle_.reset();
388	  state_pub_.reset();
389	  event_pub_.reset();
390	  plan_pub_.reset();
391	  topology_pub_.reset();
392	  last_deadlock_findings_.clear();
393	  tracking_error_sub_.reset();
394	  odom_sub_.reset();
395	  queue_.reset();
396	  reservation_table_.reset();
397	  event_log_.reset();
398	  deadlock_detector_.reset();
399	  recovery_policy_.reset();
400	  planner_.reset();
401	  catalog_reloader_.reset();
402	  reload_timer_.reset();
403	  queue_start_requested_ = false;
404	  tracking_mission_id_.clear();
405	  active_missions_.clear();
406	  return CallbackReturn::SUCCESS;
407	}
