413	void DispatcherNode::SubmitOrderCb(
414	    const std::shared_ptr<amr_dispatcher_interfaces::srv::SubmitOrder::Request> req,
415	    std::shared_ptr<amr_dispatcher_interfaces::srv::SubmitOrder::Response> resp) {
416	  if (!queue_) {
417	    resp->accepted = false;
418	    resp->message = "Dispatcher not configured";
419	    return;
420	  }
421	
422	  // 订单路由：经 submit_order 行为树调用路由器，决定订单类型语义与字段回填。
423	  // 未知/空类型由路由器统一拒绝（message 带 supported 列表）。
424	  amr_dispatcher_bt::SubmitOrderBehaviorTreeInput route_input;
425	  route_input.request.order_id = req->order_id.empty() ? req->mission_id : req->order_id;
426	  route_input.request.order_type = req->mission_type.empty() ? "transport" : req->mission_type;
427	  route_input.request.priority = req->priority;
428	  const auto route_result = amr_dispatcher_bt::TickSubmitOrderBehaviorTree(route_input);
429	  if (!route_result.success || !route_result.route) {
430	    resp->accepted = false;
431	    resp->mission_id = req->mission_id;
432	    resp->message = "route rejected: " + route_result.message;
433	    RCLCPP_WARN(get_logger(), "SubmitOrder rejected by router: %s", resp->message.c_str());
434	    return;
435	  }
436	  const auto& route = *route_result.route;
437	
438	  amr_dispatcher_core::dispatcher::Mission m;
439	  // B4：id/sequence 同源——自动 id 用戳记器保证 "m_<n>" 与 sequence=n 一致；
440	  // 调用方显式给 id 时仍消费一次序列号，保持全局单调。
441	  if (req->mission_id.empty()) {
442	    StampMissionIdentity(m, next_sequence_);
443	  } else {
444	    m.id = req->mission_id;
445	    m.sequence = next_sequence_++;
446	  }
447	  m.order_id = req->order_id.empty() ? ("ord_" + m.id) : req->order_id;
448	  m.type = route.normalized_order_type.empty() ? "transport" : route.normalized_order_type;
449	  // 站点字段优先取请求显式值，路由器解析出的站点作兜底
450	  m.pickup_station = req->pickup_station.empty() ? route.pickup_station : req->pickup_station;
451	  m.dropoff_station = req->dropoff_station.empty() ? route.dropoff_station : req->dropoff_station;
452	  m.priority = req->priority;
453	  m.deadline_unix_ms = req->deadline_unix_ms;
454	  m.expected_seconds = req->expected_seconds;
455	
456	  auto res = queue_->Push(m);
457	  resp->accepted = res.accepted;
458	  resp->mission_id = m.id;
459	  resp->message = res.message;
460	
461	  if (res.accepted) {
462	    if (route.start_if_idle) {
463	      queue_start_requested_ = true;
464	    }
465	    RCLCPP_INFO(get_logger(),
466	                "SubmitOrder routed via BT: branch=%s kind=%d type=%s start_if_idle=%d",
467	                route_result.branch.c_str(), static_cast<int>(route.kind), m.type.c_str(),
468	                route.start_if_idle ? 1 : 0);
469	    amr_dispatcher_core::dispatcher::MissionEvent evt;
470	    evt.stamp = "now";
471	    evt.mission_id = m.id;
472	    evt.event = "queued";
473	    event_log_->Append(evt);
474	
475	    if (event_pub_ && event_pub_->is_activated()) {
476	      amr_dispatcher_interfaces::msg::MissionEvent msg;
477	      msg.stamp = now();
478	      msg.mission_id = m.id;
479	      msg.order_id = m.order_id;
480	      msg.event = "queued";
481	      msg.to_state = "PENDING";
482	      msg.reason = "submitted";
483	      event_pub_->publish(msg);
484	    }
485	  }
486	}
487	
488	void DispatcherNode::CancelOrderCb(
489	    const std::shared_ptr<amr_dispatcher_interfaces::srv::CancelOrder::Request> req,
490	    std::shared_ptr<amr_dispatcher_interfaces::srv::CancelOrder::Response> resp) {
491	  if (!queue_) {
492	    resp->success = false;
493	    resp->message = "Dispatcher not active";
494	    return;
495	  }
496	  if (!req->mission_id.empty()) {
497	    bool ok = queue_->Cancel(req->mission_id);
498	    if (ok) {
499	      // action 提交的任务在排队中被取消：helper 终结 handle + 释放 HandleGoal 预占
500	      CleanupMissionCancel(req->mission_id, "mission canceled by operator");
501	      resp->success = true;
502	      resp->canceled_count = 1;
503	      resp->message = "Mission canceled from queue";
504	    } else {
505	      auto it = active_missions_.find(req->mission_id);
506	      if (it != active_missions_.end()) {
507	        // 释放资源锁；若该任务正在占用 /plan，发空路径停车
508	        if (reservation_table_) {
509	          reservation_table_->Release(req->mission_id);
510	        }
511	        if (tracking_mission_id_ == req->mission_id) {
512	          tracking_mission_id_.clear();
513	          if (plan_pub_ && plan_pub_->is_activated()) {
514	            nav_msgs::msg::Path empty;
515	            empty.header.stamp = now();
516	            empty.header.frame_id = "map";
517	            plan_pub_->publish(empty);
518	          }
519	        }
520	        active_missions_.erase(it);
521	        // helper：终结 ExecuteMission goal（未受理 action cancel → 降级 abort(3)）
522	        // 并级联取消在途 NavigateSequence goal（清 pending_nav_*）
523	        CleanupMissionCancel(req->mission_id, "mission canceled by operator");
524	        resp->success = true;
525	        resp->canceled_count = 1;
526	        resp->message = "Active mission canceled";
527	      } else {
528	        resp->success = false;
529	        resp->canceled_count = 0;
530	        resp->message = "Mission not found";
531	      }
532	    }
533	    ReArmQueueStartRequest();  // 取消活动任务后，队列后续任务需重新武装启动请求
534	    return;
535	  }
536	  if (!req->order_id.empty()) {
537	    // 整单批量取消：取消前对在队任务取证（仅存在 action handle 时取证，plan 模式零开销），
538	    // 取消成功后逐个收口 handle/预占/pending_nav（审查 I5）
539	    std::vector<std::string> action_mission_ids;
540	    if (!execute_goal_handles_.empty()) {
541	      for (const auto& qm : queue_->Snapshot()) {
542	        if (qm.order_id == req->order_id) {
543	          action_mission_ids.push_back(qm.id);
544	        }
545	      }
546	    }
547	    std::size_t count = queue_->CancelOrder(req->order_id);
548	    for (const auto& id : action_mission_ids) {
549	      CleanupMissionCancel(id, "mission canceled by operator");
550	    }
551	    resp->success = true;
552	    resp->canceled_count = static_cast<uint32_t>(count);
553	    resp->message = "Order canceled, count=" + std::to_string(count);
554	    ReArmQueueStartRequest();
555	    return;
556	  }
557	  resp->success = false;
558	  resp->message = "Neither mission_id nor order_id specified";
559	}
560	
561	void DispatcherNode::PauseMissionCb(
562	    const std::shared_ptr<amr_dispatcher_interfaces::srv::PauseMission::Request> req,
563	    std::shared_ptr<amr_dispatcher_interfaces::srv::PauseMission::Response> resp) {
