639	    const auto start_bt = amr_dispatcher_bt::TickQueuedMissionStartBehaviorTree(start_input);
640	    if (start_bt.success && start_bt.decision.request_queue_start) {
641	      queue_start_requested_ = true;
642	    }
643	    RCLCPP_INFO(get_logger(), "EnqueueMission via BT: branch=%s request_queue_start=%d",
