648	void DispatcherNode::CancelQueuedMissionCb(
649	    const std::shared_ptr<amr_dispatcher_interfaces::srv::CancelQueuedMission::Request> req,
650	    std::shared_ptr<amr_dispatcher_interfaces::srv::CancelQueuedMission::Response> resp) {
651	  if (!queue_) {
652	    resp->success = false;
653	    resp->message = "Dispatcher unconfigured";
654	    resp->queue_size = 0;
655	    return;
656	  }
657	  bool canceled = queue_->Cancel(req->mission_id);
658	  if (canceled) {
659	    // 排队取消命中：收口该任务的 action goal/handle 预占/pending_nav（审查 I5）
660	    CleanupMissionCancel(req->mission_id, "mission canceled by operator");
661	  } else {
662	    // 按整单取消：取消前取证该订单在队任务，取消成功后逐个收口（审查 I5）
663	    std::vector<std::string> action_mission_ids;
664	    if (!execute_goal_handles_.empty()) {
665	      for (const auto& qm : queue_->Snapshot()) {
666	        if (qm.order_id == req->mission_id) {
667	          action_mission_ids.push_back(qm.id);
668	        }
669	      }
670	    }
671	    const std::size_t order_count = queue_->CancelOrder(req->mission_id);
672	    canceled = (order_count > 0);
673	    for (const auto& id : action_mission_ids) {
674	      CleanupMissionCancel(id, "mission canceled by operator");
675	    }
676	  }
677	  if (req->cancel_active) {
678	    bool erased = false;
679	    {
680	      std::lock_guard<std::mutex> lock(active_missions_mutex_);
681	      erased = (active_missions_.erase(req->mission_id) > 0);
682	    }
683	    if (erased) {
684	      canceled = true;
685	      if (reservation_table_) {
686	        reservation_table_->Release(req->mission_id);
687	      }
688	      // 若被取消的是正在跟踪 /plan 的任务，发空路径停车
689	      if (tracking_mission_id_ == req->mission_id) {
690	        tracking_mission_id_.clear();
691	        if (plan_pub_ && plan_pub_->is_activated()) {
692	          nav_msgs::msg::Path empty;
693	          empty.header.stamp = now();
694	          empty.header.frame_id = "map";
695	          plan_pub_->publish(empty);
696	        }
697	      }
698	      // 活动任务取消同样收口 action goal 与在途导航 goal（cancel_active 路径，审查 I5）
699	      CleanupMissionCancel(req->mission_id, "mission canceled by operator");
700	    }
701	  }
702	  resp->success = canceled;
703	  resp->message = canceled ? "Mission canceled: " + req->mission_id : "Mission not found: " + req->mission_id;
704	  resp->queue_size = static_cast<int32_t>(queue_->size());
705	}
