742	void DispatcherNode::EstimateMissionCostCb(
743	    const std::shared_ptr<amr_dispatcher_interfaces::srv::EstimateMissionCost::Request> req,
744	    std::shared_ptr<amr_dispatcher_interfaces::srv::EstimateMissionCost::Response> resp) {
745	  // B5：真实现——mission_file 作为站点对编码（"from->to" 或 "from:to"），
746	  // 用 StationCatalog 直线距离和喂 EstimateDistanceCost；电池参数无 srv 字段，
747	  // 沿用核心测试约定（0.1 V/m，最低 21.0 V 与 charging workflow 阈值一致）。
748	  resp->mission_id = req->mission_file;
749	
750	  const std::string& spec = req->mission_file;
751	  std::string from;
752	  std::string to;
753	  const auto arrow = spec.find("->");
754	  if (arrow != std::string::npos) {
755	    from = spec.substr(0, arrow);
756	    to = spec.substr(arrow + 2);
757	  } else {
758	    const auto colon = spec.find(':');
759	    if (colon != std::string::npos) {
760	      from = spec.substr(0, colon);
761	      to = spec.substr(colon + 1);
762	    }
763	  }
764	  if (from.empty() || to.empty()) {
765	    resp->success = false;
766	    resp->message = "mission_file must encode a station pair as 'from->to' or 'from:to', got: " + spec;
767	    return;
768	  }
769	  if (!catalog_reloader_ || !catalog_reloader_->loaded()) {
770	    resp->success = false;
771	    resp->message = "station catalog not loaded";
772	    return;
773	  }
774	  const auto& catalog = catalog_reloader_->catalog();
775	  const auto* from_st = amr_dispatcher_core::catalog::FindStation(catalog, from);
776	  const auto* to_st = amr_dispatcher_core::catalog::FindStation(catalog, to);
777	  if (!from_st || !to_st) {
778	    resp->success = false;
779	    resp->message = "unknown station(s) in mission_file '" + spec + "'";
780	    return;
781	  }
782	
783	  const double distance_m =
784	      std::hypot(to_st->x - from_st->x, to_st->y - from_st->y);
785	  constexpr int kTwoStationWaypoints = 2;  // 取/送 2 站点 = 1 航段
786	  constexpr double kBatteryDropPerMeter = 0.1;    // 单位里程压降（V/m）
787	  constexpr double kMinimumBatteryVoltage = 21.0; // 与 charging workflow 阈值一致
788	
789	  const auto estimate = amr_dispatcher_core::workflow::EstimateDistanceCost(
790	      distance_m, kTwoStationWaypoints, req->nominal_speed_mps, req->battery_voltage,
791	      kBatteryDropPerMeter, kMinimumBatteryVoltage, "station_catalog_straight");
792	
793	  resp->success = true;
794	  resp->message = "estimated via station catalog straight-line distance";
795	  resp->waypoint_count = estimate.waypoint_count;
796	  resp->distance_m = estimate.distance_m;
797	  resp->eta_sec = estimate.eta_sec;
798	  resp->battery_drop_v = estimate.battery_drop_v;
799	  resp->projected_battery_voltage = estimate.projected_battery_voltage;
800	  resp->battery_sufficient = estimate.battery_sufficient;
801	}
