818	void DispatcherNode::DetectTrafficDeadlockCb(
819	    const std::shared_ptr<amr_dispatcher_interfaces::srv::DetectTrafficDeadlock::Request> /*req*/,
820	    std::shared_ptr<amr_dispatcher_interfaces::srv::DetectTrafficDeadlock::Response> resp) {
821	  if (!deadlock_detector_) {
822	    resp->success = false;
823	    resp->deadlocked = false;
824	    resp->message = "Deadlock detector unconfigured";
825	    return;
826	  }
827	  // 快照组包与 DeadlockTick 共用 helper：服务入口与定时检测结论不分叉；
828	  // 沿用本回调既有的 active_missions_ 加锁约定（helper 自身不带锁）
829	  amr_dispatcher_core::dispatcher::DeadlockSnapshot snap;
830	  {
831	    std::lock_guard<std::mutex> lock(active_missions_mutex_);
832	    snap = BuildDeadlockSnapshot();
833	  }
834	  const auto findings = deadlock_detector_->Detect(snap);
835	  resp->success = true;
836	  resp->deadlocked = !findings.empty();
837	  resp->message = resp->deadlocked ? "Deadlock detected in graph" : "No deadlock detected";
838	  for (const auto& f : findings) {
839	    for (const auto& mid : f.mission_ids) {
840	      resp->mission_ids.push_back(mid);
841	    }
842	    // cycle_path 为任务/资源交替闭合序列：奇数位才是资源 id（任务 id 不得混入）
843	    for (std::size_t i = 1; i < f.cycle_path.size(); i += 2) {
844	      resp->conflict_resource_ids.push_back(f.cycle_path[i]);
845	    }
846	    resp->descriptions.push_back(f.description);
847	  }
848	}
