904	void DispatcherNode::GetOperatorSnapshotCb(
905	    const std::shared_ptr<amr_dispatcher_interfaces::srv::GetOperatorSnapshot::Request> req,
906	    std::shared_ptr<amr_dispatcher_interfaces::srv::GetOperatorSnapshot::Response> resp) {
907	  // B5：真实现——BuildOperatorSnapshotProjection 字段全量投影。
908	  // 无 fleet/facility/business 后端时对应字段传 nullptr 透传为空集合。
909	  amr_dispatcher_core::workflow::OperatorSnapshotRequest snap_req;
910	  {
911	    std::lock_guard<std::mutex> lock(active_missions_mutex_);
912	    snap_req.mission_active = !active_missions_.empty();
913	    if (!active_missions_.empty()) {
914	      snap_req.active_mission_id = active_missions_.begin()->first;
915	      snap_req.mission_state = "ACTIVE";
916	    } else {
917	      snap_req.mission_state = "IDLE";
918	    }
919	  }
920	
921	  if (queue_) {
922	    for (const auto& m : queue_->Snapshot()) {
923	      amr_dispatcher_core::workflow::QueuedMission qm;
924	      qm.profile.mission_id = m.id;
925	      qm.mission_file = m.order_id;
926	      qm.priority = m.priority;
927	      qm.sequence = m.sequence;
928	      snap_req.mission_queue.push_back(qm);
929	      // 队列按 order_id 记暂停：探测本任务所属订单是否被暂停
930	      if (!m.order_id.empty() && queue_->IsOrderPaused(m.order_id)) {
931	        snap_req.paused_workflow_order_ids.insert(m.order_id);
932	      }
933	    }
934	    snap_req.paused = !snap_req.paused_workflow_order_ids.empty();
935	  }
936	
937	  if (event_log_) {
938	    const std::size_t limit = amr_dispatcher_core::dispatcher::MissionEventLog::NormalizeLimit(
939	        req->event_limit, 10, 100);
940	    for (const auto& evt : event_log_->Recent(limit)) {
941	      amr_dispatcher_core::workflow::MissionEvent wfe;
942	      wfe.stamp = evt.stamp;
943	      wfe.mission_id = evt.mission_id;
944	      wfe.state = evt.event;          // dispatcher 事件名 -> workflow 状态字段
945	      wfe.previous_state = evt.previous_event;
946	      wfe.message = evt.message;
947	      wfe.recoverable = evt.recoverable;
948	      snap_req.mission_events.push_back(wfe);
949	    }
950	  }
951	  snap_req.event_limit = req->event_limit;
952	
953	  const auto proj = amr_dispatcher_core::workflow::BuildOperatorSnapshotProjection(snap_req);
954	  resp->success = proj.success;
955	  resp->message = proj.message;
956	  resp->mission_state = proj.mission_state;
957	  resp->previous_mission_state = proj.previous_mission_state;
958	  resp->active_mission_id = proj.active_mission_id;
959	  resp->mission_message = proj.mission_message;
960	  resp->recoverable = proj.recoverable;
961	  resp->mission_active = proj.mission_active;
962	  resp->paused = proj.paused;
963	  resp->queue_size = proj.queue_size;
964	  resp->queued_mission_ids = proj.queued_mission_ids;
965	  resp->queued_priorities = proj.queued_priorities;
966	  resp->paused_workflow_order_ids = proj.paused_workflow_order_ids;
967	  resp->fleet_robot_ids = proj.fleet_robot_ids;
968	  resp->fleet_enabled = proj.fleet_enabled;
969	  resp->fleet_states = proj.fleet_states;
970	  resp->fleet_battery_voltage = proj.fleet_battery_voltage;
971	  resp->fleet_current_station_ids = proj.fleet_current_station_ids;
972	  resp->fleet_capabilities = proj.fleet_capabilities;
973	  resp->remote_task_ids = proj.remote_task_ids;
974	  resp->remote_task_robot_ids = proj.remote_task_robot_ids;
975	  resp->remote_task_states = proj.remote_task_states;
976	  resp->facility_resource_ids = proj.facility_resource_ids;
977	  resp->facility_resource_types = proj.facility_resource_types;
978	  resp->facility_station_ids = proj.facility_station_ids;
979	  resp->facility_available = proj.facility_available;
980	  resp->facility_status = proj.facility_status;
981	  resp->business_types = proj.business_types;
982	  resp->business_scenario_ids = proj.business_scenario_ids;
983	  resp->business_workflow_ids = proj.business_workflow_ids;
984	  resp->recent_event_stamp = proj.recent_event_stamp;
985	  resp->recent_event_mission_ids = proj.recent_event_mission_ids;
986	  resp->recent_event_states = proj.recent_event_states;
987	  resp->recent_event_messages = proj.recent_event_messages;
