990	void DispatcherNode::ValidateSiteConfigCb(
991	    const std::shared_ptr<amr_dispatcher_interfaces::srv::ValidateSiteConfig::Request> req,
992	    std::shared_ptr<amr_dispatcher_interfaces::srv::ValidateSiteConfig::Response> resp) {
993	  // B5：真实现——真实尝试加载 stations_file；同时校验 dispatcher 最小参数集合。
994	  // bundle_dir 指定 bundle 时优先用 <bundle_dir>/stations.yaml，否则回退节点参数路径。
995	  resp->version_id = req->version_id.empty() ? "v1.0.0" : req->version_id;
996	
997	  std::string stations_path = get_parameter("stations_file").as_string();
998	  if (!req->bundle_dir.empty()) {
999	    stations_path = req->bundle_dir + "/stations.yaml";
1000	  }
1001	  resp->checked_files.push_back(stations_path);
1002	
1003	  const auto catalog_opt = amr_dispatcher_core::catalog::LoadStationCatalog(stations_path);
1004	  if (!catalog_opt) {
1005	    resp->success = false;
1006	    resp->errors.push_back("stations_file load failed: " + stations_path);
1007	    resp->message = "validation failed: " + stations_path + " not parseable";
1008	    return;
1009	  }
1010	  if (catalog_opt->stations.empty()) {
1011	    resp->success = false;
1012	    resp->errors.push_back("stations catalog empty: " + stations_path);
1013	    resp->message = "validation failed: no stations defined";
1014	    return;
1015	  }
1016	
1017	  // 最小参数集合校验：任一失败即整体失败
1018	  const int queue_capacity = get_parameter("queue_capacity").as_int();
1019	  if (queue_capacity <= 0) {
1020	    resp->errors.push_back("queue_capacity must be > 0, got " + std::to_string(queue_capacity));
1021	  }
1022	  const double sched_hz = get_parameter("schedule_rate_hz").as_double();
1023	  if (sched_hz <= 0.0) {
1024	    resp->errors.push_back("schedule_rate_hz must be > 0, got " + std::to_string(sched_hz));
1025	  }
1026	  const double deadlock_hz = get_parameter("deadlock_check_rate_hz").as_double();
1027	  if (deadlock_hz <= 0.0) {
1028	    resp->errors.push_back("deadlock_check_rate_hz must be > 0, got " + std::to_string(deadlock_hz));
1029	  }
1030	  const int max_active = get_parameter("max_active_missions").as_int();
1031	  if (max_active < 1) {
1032	    resp->errors.push_back("max_active_missions must be >= 1, got " + std::to_string(max_active));
1033	  }
1034	  const std::string comparator = get_parameter("comparator").as_string();
1035	  if (!amr_dispatcher_core::dispatcher::CreateMissionComparator(comparator)) {
1036	    resp->errors.push_back("unknown comparator: " + comparator);
1037	  }
1038	
1039	  resp->success = resp->errors.empty();
1040	  resp->message = resp->success
1041	                      ? "site configuration validation passed"
1042	                      : "validation failed: " + std::to_string(resp->errors.size()) + " error(s)";
1043	}
1044	
1045	rclcpp_action::GoalResponse DispatcherNode::HandleGoal(
1046	    const rclcpp_action::GoalUUID& /*uuid*/,
1047	    std::shared_ptr<const ExecuteMission::Goal> goal) {
1048	  if (!goal || goal->mission_id.empty()) {
1049	    RCLCPP_WARN(get_logger(), "ExecuteMission goal rejected: empty mission_id");
1050	    return rclcpp_action::GoalResponse::REJECT;
1051	  }
1052	  if ((queue_ && queue_->Contains(goal->mission_id)) ||
1053	      active_missions_.count(goal->mission_id) > 0) {
1054	    RCLCPP_WARN(get_logger(), "ExecuteMission goal rejected: duplicate mission_id %s",
1055	                goal->mission_id.c_str());
1056	    return rclcpp_action::GoalResponse::REJECT;
1057	  }
1058	  // required_resources 可预占：Reserve 原子性（不落任何锁即失败），失败即 REJECT
1059	  if (!goal->required_resources.empty()) {
1060	    if (!reservation_table_) {
1061	      RCLCPP_WARN(get_logger(),
1062	                  "ExecuteMission goal rejected: reservation table unavailable for %s",
1063	                  goal->mission_id.c_str());
1064	      return rclcpp_action::GoalResponse::REJECT;
1065	    }
1066	    auto res = reservation_table_->Reserve(goal->mission_id, goal->required_resources);
1067	    if (!res.success) {
1068	      RCLCPP_WARN(get_logger(), "ExecuteMission goal rejected: reserve failed for %s: %s",
1069	                  goal->mission_id.c_str(), res.message.c_str());
1070	      return rclcpp_action::GoalResponse::REJECT;
1071	    }
1072	  }
1073	  // DEFER + HandleAccepted 里显式 execute()：不受框架是否隐式 execute 影响的稳妥路径
1074	  return rclcpp_action::GoalResponse::ACCEPT_AND_DEFER;
1075	}
