1077	rclcpp_action::CancelResponse DispatcherNode::HandleCancel(
1078	    const std::shared_ptr<GoalHandleExecute> goal_handle) {
1079	  if (execute_goal_handles_.find(goal_handle->get_goal()->mission_id) ==
1080	      execute_goal_handles_.end()) {
1081	    return rclcpp_action::CancelResponse::REJECT;
1082	  }
1083	  // 只受理取消请求：rclcpp_action 在本回调返回 ACCEPT 之后才把 goal 迁移到
1084	  // CANCELING，而 canceled() 只允许在 CANCELING 态调用——
1085	  // 实际的任务取消与 goal 终结延后到 ProcessActionCancels（ScheduleTick 内）。
1086	  return rclcpp_action::CancelResponse::ACCEPT;
1087	}
1088	
1089	void DispatcherNode::HandleAccepted(const std::shared_ptr<GoalHandleExecute> goal_handle) {
1090	  const auto goal = goal_handle->get_goal();
1091	  // ACCEPTED -> EXECUTING：后续 publish_feedback/succeed/abort 的前置条件
1092	  goal_handle->execute();
1093	
1094	  if (!queue_) {
1095	    if (reservation_table_) {
1096	      reservation_table_->Release(goal->mission_id);
1097	    }
1098	    auto result = std::make_shared<ExecuteMission::Result>();
1099	    result->success = false;
1100	    result->error_code = 1;
1101	    result->message = "dispatcher not configured";
1102	    goal_handle->abort(result);
1103	    return;
1104	  }
1105	
1106	  amr_dispatcher_core::dispatcher::Mission m;
1107	  m.id = goal->mission_id;
1108	  m.order_id = goal->mission_id;  // 订单号=任务号，保证整单取消可寻址
1109	  m.priority = goal->priority;
1110	  m.dropoff_station = goal->target_station;
1111	  if (goal->deadline_seconds > 0.0) {
1112	    m.deadline_unix_ms =
1113	        std::chrono::duration_cast<std::chrono::milliseconds>(
1114	            std::chrono::system_clock::now().time_since_epoch())
1115	            .count() +
1116	        static_cast<std::int64_t>(goal->deadline_seconds * 1000.0);
1117	  }
1118	  m.state = amr_dispatcher_core::dispatcher::MissionState::kPending;
1119	  m.sequence = next_sequence_++;
1120	
1121	  auto push = queue_->Push(m);
1122	  if (!push.accepted) {
1123	    // 入队失败回滚 HandleGoal 的资源预占并 abort（死锁风险下的显式失败出口）
1124	    if (reservation_table_) {
1125	      reservation_table_->Release(m.id);
1126	    }
1127	    auto result = std::make_shared<ExecuteMission::Result>();
1128	    result->success = false;
1129	    result->error_code = 1;
1130	    result->message = "enqueue rejected: " + push.message;
1131	    goal_handle->abort(result);
1132	    RCLCPP_WARN(get_logger(), "ExecuteMission enqueue rejected for %s: %s", m.id.c_str(),
1133	                push.message.c_str());
1134	    return;
1135	  }
1136	
1137	  execute_goal_handles_[m.id] = goal_handle;
1138	  queue_start_requested_ = true;  // action 提交的任务武装 runtime 出队启动请求
1139	  RCLCPP_INFO(get_logger(),
1140	              "ExecuteMission accepted: %s -> queued (target=%s, prio=%d, resources=%zu)",
1141	              m.id.c_str(), m.dropoff_station.c_str(), m.priority,
1142	              goal->required_resources.size());
1143	}
1144	
1145	void DispatcherNode::FinishExecuteGoal(const std::string& mission_id, ExecuteFinish kind,
1146	                                        const std::string& message, std::int32_t error_code) {
1147	  auto it = execute_goal_handles_.find(mission_id);
1148	  if (it == execute_goal_handles_.end()) {
1149	    return;
1150	  }
1151	  auto handle = it->second;
1152	  execute_goal_handles_.erase(it);
1153	
1154	  // total_duration_sec：按派发时刻计时（排队中取消等未派发场景为 0），
1155	  // 计时后即遗忘时间戳，防止 map 长期驻留
1156	  double duration_sec = 0.0;
1157	  auto dispatch_time = mission_dispatch_time_.find(mission_id);
1158	  if (dispatch_time != mission_dispatch_time_.end()) {
1159	    duration_sec = std::chrono::duration<double>(
1160	                       std::chrono::steady_clock::now() - dispatch_time->second)
1161	                       .count();
1162	    mission_dispatch_time_.erase(dispatch_time);
1163	  }
1164	  if (!handle || !handle->is_active()) {
1165	    return;
1166	  }
1167	
1168	  auto result = std::make_shared<ExecuteMission::Result>();
1169	  result->success = (kind == ExecuteFinish::kSucceed);
1170	  result->error_code = error_code;
1171	  result->message = message;
1172	  result->total_duration_sec = duration_sec;
1173	  try {
1174	    if (handle->is_canceling()) {
1175	      // 已受理 action cancel：只能走 canceled()（rclcpp_action 状态机约束）
1176	      handle->canceled(result);
1177	    } else if (handle->is_executing()) {
1178	      if (kind == ExecuteFinish::kSucceed) {
1179	        handle->succeed(result);
1180	      } else {
1181	        // kAbort 与服务侧取消（未进入 CANCELING 无法 canceled()）降级为 abort
1182	        handle->abort(result);
1183	      }
1184	    } else {
1185	      // ACCEPTED 未执行的兜底：先 execute 再 abort，避免 rclcpp_action 状态断言
1186	      handle->execute();
1187	      handle->abort(result);
1188	    }
1189	    RCLCPP_INFO(get_logger(), "ExecuteMission goal finished: %s kind=%d (%s)",
1190	                mission_id.c_str(), static_cast<int>(kind), message.c_str());
1191	  } catch (const std::exception& ex) {
1192	    RCLCPP_ERROR(get_logger(), "FinishExecuteGoal(%s) failed: %s", mission_id.c_str(), ex.what());
1193	  }
1194	}
