1196	void DispatcherNode::CleanupMissionCancel(const std::string& mission_id,
1197	                                          const std::string& reason) {
1198	  // HandleGoal 预占的 required_resources 随任务取消一并释放（plan 模式无 handle 时
1199	  // Release 对无锁持有者是无操作，与既有行为一致）
1200	  const bool has_handle = execute_goal_handles_.count(mission_id) > 0;
1201	  if (has_handle && reservation_table_) {
1202	    reservation_table_->Release(mission_id);
1203	  }
1204	  // action 模式级联：取消在途 NavigateSequence goal 并清 pending 标记
1205	  if (navigation_backend_ == "action" && pending_nav_mission_id_ == mission_id) {
1206	    if (nav_client_ && pending_nav_goal_handle_) {
1207	      nav_client_->async_cancel_goal(pending_nav_goal_handle_);
1208	    }
1209	    pending_nav_mission_id_.clear();
1210	    pending_nav_goal_handle_.reset();
1211	  }
1212	  if (has_handle) {
1213	    // 服务侧取消未受理 action cancel（handle 不在 CANCELING），降级 abort(3 PREEMPTED)
1214	    // （total_duration_sec 的时间戳由 FinishExecuteGoal 计时后遗忘）
1215	    FinishExecuteGoal(mission_id, ExecuteFinish::kCanceled, reason, 3);
1216	  } else {
1217	    mission_dispatch_time_.erase(mission_id);
1218	  }
1219	  ForgetMissionDispatchState(mission_id);
1220	}
