1222	void DispatcherNode::ForgetMissionDispatchState(const std::string& mission_id) {
1223	  // 路由锁预留记账、排队等待记录与派发起点同步遗忘：
1224	  // 幂等，供 Complete/Fail/取消/死锁取消/预占判负等终态路径共用
1225	  mission_reserved_at_.erase(mission_id);
1226	  pending_wait_.erase(mission_id);
1227	  mission_dispatch_start_.erase(mission_id);
1228	}
