1230	void DispatcherNode::ProcessActionCancels() {
1231	  if (execute_goal_handles_.empty()) {
1232	    return;
1233	  }
1234	  std::vector<std::string> canceling;
1235	  canceling.reserve(execute_goal_handles_.size());
1236	  for (const auto& [id, handle] : execute_goal_handles_) {
1237	    if (handle && handle->is_canceling()) {
1238	      canceling.push_back(id);
1239	    }
1240	  }
1241	  for (const auto& id : canceling) {
1242	    RCLCPP_INFO(get_logger(), "ExecuteMission cancel accepted by action client: %s", id.c_str());
1243	    bool canceled = false;
1244	    if (queue_ && queue_->Cancel(id)) {
1245	      // 排队中任务被 action 取消：连带释放 HandleGoal 预占的 required_resources
1246	      if (reservation_table_) {
1247	        reservation_table_->Release(id);
1248	      }
1249	      canceled = true;
1250	    } else {
1251	      auto it = active_missions_.find(id);
1252	      if (it != active_missions_.end()) {
1253	        if (reservation_table_) {
1254	          reservation_table_->Release(id);
1255	        }
1256	        if (tracking_mission_id_ == id) {
1257	          tracking_mission_id_.clear();
1258	          if (plan_pub_ && plan_pub_->is_activated()) {
1259	            nav_msgs::msg::Path empty;
1260	            empty.header.stamp = now();
1261	            empty.header.frame_id = "map";
1262	            plan_pub_->publish(empty);
1263	          }
1264	        }
1265	        active_missions_.erase(it);
1266	        canceled = true;
1267	      }
1268	    }
1269	    ForgetMissionDispatchState(id);  // 取消终态：路由锁记账/等待记录/派发起点遗忘
1270	    // action 模式级联：取消在途的 NavigateSequence goal 并清 pending 标记
1271	    if (navigation_backend_ == "action" && pending_nav_mission_id_ == id) {
1272	      if (nav_client_ && pending_nav_goal_handle_) {
1273	        nav_client_->async_cancel_goal(pending_nav_goal_handle_);
1274	      }
1275	      pending_nav_mission_id_.clear();
1276	      pending_nav_goal_handle_.reset();
1277	    }
1278	    // 此时 handle 已确认 is_canceling()，canceled() 状态合法
1279	    FinishExecuteGoal(id, ExecuteFinish::kCanceled, "mission canceled by action client", 3);
1280	    if (canceled) {
1281	      ReArmQueueStartRequest();
1282	    }
1283	  }
1284	}
