1286	void DispatcherNode::NavGoalResponseCb(const std::string& mission_id,
1287	                                       const GoalHandleNavigate::SharedPtr& goal_handle) {
1288	  if (!goal_handle) {
1289	    RCLCPP_WARN(get_logger(), "NavigateSequence goal rejected by bridge for mission %s",
1290	                mission_id.c_str());
1291	    if (pending_nav_mission_id_ == mission_id) {
1292	      pending_nav_mission_id_.clear();
1293	      pending_nav_goal_handle_.reset();
1294	    }
1295	    // FailMission 内部会清理 tracking 槽位与空路径停车
1296	    FailMission(mission_id, "navigate_sequence goal rejected by bridge");
1297	    return;
1298	  }
1299	  // goal 响应到达时任务可能已被取消/完结：孤儿 goal 直接取消，
1300	  // 否则 bridge 盲跑 + pending 句柄残留（审查 I4）
1301	  bool mission_alive;
1302	  {
1303	    std::lock_guard<std::mutex> lock(active_missions_mutex_);
1304	    mission_alive = active_missions_.count(mission_id) > 0;
1305	  }
1306	  if (!mission_alive) {
1307	    RCLCPP_WARN(get_logger(),
1308	                "Stale NavigateSequence goal response for %s (mission gone); canceling orphan goal",
1309	                mission_id.c_str());
1310	    nav_client_->async_cancel_goal(goal_handle);
1311	    if (pending_nav_mission_id_ == mission_id) {
1312	      pending_nav_mission_id_.clear();
1313	      pending_nav_goal_handle_.reset();
1314	    }
1315	    return;
1316	  }
1317	  pending_nav_goal_handle_ = goal_handle;
1318	}
