1320	void DispatcherNode::NavFeedbackCb(
1321	    const std::string& mission_id, const GoalHandleNavigate::SharedPtr& /*goal_handle*/,
1322	    const std::shared_ptr<const NavigateSequence::Feedback> feedback) {
1323	  mission_last_progress_[mission_id] = std::chrono::steady_clock::now();  // 喂死锁 idle 启发式
1324	  if (!feedback) {
1325	    return;
1326	  }
1327	  // NavigateSequence feedback -> ExecuteMission feedback 映射
1328	  // （current_index/total -> state_code=2 EXECUTING + percent=index/total*100）
1329	  auto hit = execute_goal_handles_.find(mission_id);
1330	  if (hit == execute_goal_handles_.end() || !hit->second || !hit->second->is_executing()) {
1331	    return;
1332	  }
1333	  auto fb = std::make_shared<ExecuteMission::Feedback>();
1334	  fb->state_code = 2;  // EXECUTING
1335	  fb->current_node = feedback->current_station;
1336	  fb->percent_complete =
1337	      feedback->total_waypoints > 0
1338	          ? static_cast<float>(100.0 * static_cast<double>(feedback->current_index) /
1339	                               static_cast<double>(feedback->total_waypoints))
1340	          : 0.0f;
1341	  fb->estimated_remaining_sec = 0.0;
1342	  hit->second->publish_feedback(fb);
1343	}
