1345	void DispatcherNode::NavResultCb(const std::string& mission_id,
1346	                                 const GoalHandleNavigate::WrappedResult& result) {
1347	  if (pending_nav_mission_id_ == mission_id) {
1348	    pending_nav_mission_id_.clear();
1349	    pending_nav_goal_handle_.reset();
1350	  }
1351	  if (result.code == rclcpp_action::ResultCode::SUCCEEDED && result.result &&
1352	      result.result->success) {
1353	    CompleteMission(mission_id, "navigate_sequence succeeded");
1354	    return;
1355	  }
1356	  std::string msg;
1357	  if (result.result && !result.result->message.empty()) {
1358	    msg = result.result->message;
1359	  } else if (result.code == rclcpp_action::ResultCode::CANCELED) {
1360	    msg = "navigate_sequence canceled";
1361	  } else if (result.code == rclcpp_action::ResultCode::ABORTED) {
1362	    msg = "navigate_sequence aborted";
1363	  } else {
1364	    msg = "navigate_sequence failed";
1365	  }
1366	  FailMission(mission_id, msg);
1367	}
1368	
1369	void DispatcherNode::ScheduleTick() {
1370	  // 已受理的 ExecuteMission action 取消需在提前返回之前处理（10Hz 延迟 ≤100ms）
1371	  ProcessActionCancels();
1372	  if (!queue_ || queue_->empty()) {
1373	    return;
1374	  }
1375	  const std::size_t max_active = get_parameter("max_active_missions").as_int();
1376	  if (active_missions_.size() >= max_active) {
1377	    return;
1378	  }
1379	
1380	  // 单车执行模型：同时只有一条 /plan 在跟踪，其余任务保持 active 等待车辆空闲
1381	  if (!tracking_mission_id_.empty()) {
1382	    return;
1383	  }
1384	
1385	  // 地图版本门禁：配置了期望哈希且目录已加载、且目录哈希非空时，
1386	  // 哈希不一致即判定环境地图与部署目录不匹配——暂停出队派发。
1387	  // 直接 return（不消费 queue_start_requested_），哈希恢复一致后派发自动继续。
1388	  map_version_valid_ = true;
1389	  if (!expected_map_hash_.empty() && catalog_reloader_ != nullptr &&
1390	      catalog_reloader_->loaded()) {
1391	    const auto& catalog = catalog_reloader_->catalog();
1392	    if (!catalog.map_hash.empty() && catalog.map_hash != expected_map_hash_) {
1393	      map_version_valid_ = false;
1394	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
1395	                           "Map hash mismatch: expected %s got %s, dispatching paused",
1396	                           expected_map_hash_.c_str(), catalog.map_hash.c_str());
1397	      return;
1398	    }
1399	  }
1400	
1401	  // 行为树出队派发门控：runtime 树按"空闲 + 启动请求"给派发决策，
1402	  // 未请求启动时即使队列有任务也不出队（启动请求由提单/入队/结果链武装）。
1403	  amr_dispatcher_bt::MissionRuntimeBehaviorTreeInput runtime_input;
1404	  runtime_input.tick.mission_active = !tracking_mission_id_.empty();
1405	  runtime_input.tick.queue_start_requested = queue_start_requested_;
1406	  const auto runtime_result = amr_dispatcher_bt::TickMissionRuntimeBehaviorTree(runtime_input);
1407	  if (!runtime_result.success || !runtime_result.decision.start_queued_mission) {
1408	    return;
1409	  }
1410	  queue_start_requested_ = false;  // 启动请求被本次派发消费
1411	
1412	  // Peek→Reserve→Pop（节点单线程，Peek 与 Pop 之间无竞态）：
1413	  // 先为队首任务规划路由锁并预留，成功才出队继续派发；失败则任务留在队列、
1414	  // 发 reservation_denied 事件、重新武装启动请求后本 tick 返回——既不丢任务也不违反封路。
1415	  const auto* peeked = queue_->Peek();
1416	  if (!peeked) {
1417	    return;  // 队列任务全部暂停：与 PopNext 失败等价，本 tick 结束
1418	  }
1419	  const std::string candidate_id = peeked->id;
1420	  const std::string candidate_order_id = peeked->order_id;
1421	  std::vector<std::string> route_locks;
1422	  if (catalog_reloader_ != nullptr && catalog_reloader_->loaded()) {
1423	    route_locks = amr_dispatcher_core::workflow::PlanMissionRouteLocks(
1424	        catalog_reloader_->catalog(), peeked->pickup_station, peeked->dropoff_station);
1425	  }
1426	  if (!route_locks.empty() && reservation_table_) {
1427	    auto reserve = reservation_table_->Reserve(candidate_id, route_locks);
1428	    if (!reserve.success) {
1429	      pending_wait_[candidate_id] = route_locks;  // WFG：该任务在等这批锁
1430	      RCLCPP_WARN(get_logger(), "Reservation denied for queued mission %s: %s",
1431	                  candidate_id.c_str(), reserve.message.c_str());
1432	      if (event_pub_ && event_pub_->is_activated()) {
1433	        amr_dispatcher_interfaces::msg::MissionEvent msg;
1434	        msg.stamp = now();
1435	        msg.mission_id = candidate_id;
1436	        msg.order_id = candidate_order_id;
1437	        msg.event = "reservation_denied";
1438	        msg.from_state = "PENDING";
1439	        msg.to_state = "PENDING";  // 任务留在队列，状态不变
1440	        msg.reason = reserve.message;
1441	        event_pub_->publish(msg);
1442	      }
1443	      if (event_log_) {
1444	        amr_dispatcher_core::dispatcher::MissionEvent evt;
1445	        evt.stamp = "now";
1446	        evt.mission_id = candidate_id;
1447	        evt.event = "reservation_denied";
1448	        evt.message = reserve.message;
1449	        event_log_->Append(evt);
1450	      }
1451	      ReArmQueueStartRequest();  // 队列非空 -> 稍后锁释放时重试派发
1452	      return;
1453	    }
1454	    mission_reserved_at_[candidate_id] = std::chrono::steady_clock::now();
1455	  }
1456	  pending_wait_.erase(candidate_id);  // 预留通过（或本轮无锁），历史等待记录作废
1457	
1458	  auto pop = queue_->PopNext();
1459	  if (!pop.success || !pop.mission) {
1460	    return;
1461	  }
1462	
1463	  amr_dispatcher_core::dispatcher::Mission m = *pop.mission;
1464	  m.state = amr_dispatcher_core::dispatcher::MissionState::kActive;
1465	
1466	  // 解析起终点：无 pickup 时用车辆当前位姿作起点；站点缺失或目录未加载直接判负
1467	  const amr_dispatcher_core::catalog::Station* from_st = nullptr;
1468	  const amr_dispatcher_core::catalog::Station* to_st = nullptr;
1469	  const bool catalog_loaded =
1470	      catalog_reloader_ != nullptr && catalog_reloader_->loaded();
1471	  if (catalog_loaded) {
1472	    const auto& catalog = catalog_reloader_->catalog();
1473	    if (!m.pickup_station.empty()) {
1474	      from_st = amr_dispatcher_core::catalog::FindStation(catalog, m.pickup_station);
1475	    }
1476	    if (!m.dropoff_station.empty()) {
1477	      to_st = amr_dispatcher_core::catalog::FindStation(catalog, m.dropoff_station);
1478	    }
1479	  }
1480	  if (m.dropoff_station.empty() || !to_st) {
1481	    RCLCPP_WARN(get_logger(), "Mission %s has no resolvable dropoff station (%s, catalog_loaded=%d), failing",
1482	                m.id.c_str(), m.dropoff_station.c_str(), catalog_loaded);
1483	    if (event_pub_ && event_pub_->is_activated()) {
1484	      amr_dispatcher_interfaces::msg::MissionEvent msg;
1485	      msg.stamp = now();
1486	      msg.mission_id = m.id;
1487	      msg.order_id = m.order_id;
1488	      msg.event = "plan_failed";
1489	      msg.to_state = "FAILED";
1490	      msg.reason = "unknown dropoff station: " + m.dropoff_station;
1491	      event_pub_->publish(msg);
1492	    }
1493	    // 本单已出队但被判负丢弃：Peek 阶段预留的路由锁须就地释放
1494	    //（任务不进 active_missions_，走不到 Complete/Fail 的终态清理）
1495	    if (reservation_table_) {
1496	      reservation_table_->Release(m.id);
1497	    }
1498	    ForgetMissionDispatchState(m.id);
1499	    // ExecuteMission goal 须就地 abort：该分支不经 Complete/Fail，不收口则
1500	    // action 客户端永久悬挂、handle 残留在 execute_goal_handles_（终审 F8）
1501	    //（mission_dispatch_time_ 此刻尚未写入，无需额外遗忘）
1502	    FinishExecuteGoal(m.id, ExecuteFinish::kAbort,
1503	                      "unknown dropoff station: " + m.dropoff_station, 1);
1504	    ReArmQueueStartRequest();  // 本单丢弃后，队列中其余任务仍需能被派发
1505	    return;
1506	  }
1507	
1508	  // 预留成功：持有锁列表（逗号连接）回填任务，供死锁检测长持锁启发式取证
1509	  if (!route_locks.empty()) {
1510	    std::string joined_locks;
1511	    for (const auto& lock_id : route_locks) {
1512	      if (!joined_locks.empty()) {
1513	        joined_locks += ",";
1514	      }
1515	      joined_locks += lock_id;
1516	    }
1517	    m.reservation_id = joined_locks;
1518	  }
1519	
1520	  active_missions_[m.id] = m;
1521	  mission_last_progress_[m.id] = std::chrono::steady_clock::now();
1522	
1523	  // 生成并发布路径：path_tracker 订阅 /plan 后开始输出 /cmd_vel_raw
1524	  amr_dispatcher_core::Pose2D start;
1525	  if (from_st) {
1526	    start = {from_st->x, from_st->y, from_st->yaw};
1527	  } else if (has_odom_) {
1528	    start = {current_pose_.x, current_pose_.y, current_pose_.yaw};
1529	  }
1530	  const amr_dispatcher_core::Pose2D goal{to_st->x, to_st->y, to_st->yaw};
1531	
1532	  const auto waypoints = planner_ ? planner_->Plan(start, goal) : std::vector<amr_dispatcher_core::Pose2D>{};
1533	  if (waypoints.empty() || !plan_pub_ || !plan_pub_->is_activated()) {
1534	    FailMission(m.id, "planner returned empty path");
1535	    return;
1536	  }
1537	
1538	  // 记录派发起点：ExecuteMission feedback 按此直线距离折算 percent_complete
1539	  mission_dispatch_start_[m.id] = {start.x, start.y, start.theta};
1540	  // 派发时刻：ExecuteMission result.total_duration_sec 由此计时
1541	  mission_dispatch_time_[m.id] = std::chrono::steady_clock::now();
1542	
1543	  // 执行后端：action 模式不发 /plan，改为向 /navigate_sequence 发单点 goal
1544	  //（waypoint=规划终点，station_names=[dropoff]）；默认 plan 模式以下路径不变。
1545	  if (navigation_backend_ == "action") {
1546	    if (!nav_client_) {
1547	      FailMission(m.id, "navigate_sequence client not configured");
1548	      return;
1549	    }
1550	    if (!nav_client_->action_server_is_ready()) {
1551	      FailMission(m.id, "navigate_sequence action server not available (is bridge running?)");
1552	      return;
1553	    }
1554	    const auto& wp = waypoints.back();
1555	    NavigateSequence::Goal nav_goal;
1556	    geometry_msgs::msg::PoseStamped ps;
1557	    ps.header.stamp = now();
1558	    ps.header.frame_id = "map";
1559	    ps.pose.position.x = wp.x;
1560	    ps.pose.position.y = wp.y;
1561	    ps.pose.orientation.z = std::sin(wp.theta / 2.0);
1562	    ps.pose.orientation.w = std::cos(wp.theta / 2.0);
1563	    nav_goal.waypoints.push_back(ps);
1564	    nav_goal.station_names.push_back(m.dropoff_station);
1565	    nav_goal.loop = false;
1566	
1567	    rclcpp_action::Client<NavigateSequence>::SendGoalOptions opts;
1568	    const std::string mission_id = m.id;
1569	    opts.goal_response_callback = [this, mission_id](const GoalHandleNavigate::SharedPtr& gh) {
1570	      NavGoalResponseCb(mission_id, gh);
1571	    };
1572	    opts.feedback_callback = [this, mission_id](const GoalHandleNavigate::SharedPtr& gh,
1573	                                                const std::shared_ptr<const NavigateSequence::Feedback> fb) {
1574	      NavFeedbackCb(mission_id, gh, fb);
1575	    };
1576	    opts.result_callback = [this, mission_id](const GoalHandleNavigate::WrappedResult& result) {
1577	      NavResultCb(mission_id, result);
1578	    };
1579	    // 先占住单车执行槽位再发 goal，避免 goal 响应回调前的派发空窗
1580	    pending_nav_mission_id_ = m.id;
1581	    tracking_mission_id_ = m.id;
1582	    nav_client_->async_send_goal(nav_goal, opts);
1583	
1584	    RCLCPP_INFO(get_logger(),
1585	                "Dispatched mission via NavigateSequence: %s (order=%s, type=%s, prio=%d, %s->%s)",
1586	                m.id.c_str(), m.order_id.c_str(), m.type.c_str(), m.priority,
1587	                m.pickup_station.c_str(), m.dropoff_station.c_str());
1588	
1589	    if (event_pub_ && event_pub_->is_activated()) {
1590	      amr_dispatcher_interfaces::msg::MissionEvent msg;
1591	      msg.stamp = now();
1592	      msg.mission_id = m.id;
1593	      msg.order_id = m.order_id;
1594	      msg.event = "active";
1595	      msg.from_state = "PENDING";
1596	      msg.to_state = "ACTIVE";
1597	      msg.reason = "dispatched by scheduler";
1598	      event_pub_->publish(msg);
1599	    }
1600	    return;
1601	  }
1602	
1603	  nav_msgs::msg::Path path_msg;
1604	  path_msg.header.stamp = now();
1605	  path_msg.header.frame_id = "map";
1606	  path_msg.poses.reserve(waypoints.size());
1607	  for (const auto& wp : waypoints) {
1608	    geometry_msgs::msg::PoseStamped ps;
1609	    ps.header = path_msg.header;
1610	    ps.pose.position.x = wp.x;
1611	    ps.pose.position.y = wp.y;
1612	    ps.pose.orientation.z = std::sin(wp.theta / 2.0);
1613	    ps.pose.orientation.w = std::cos(wp.theta / 2.0);
1614	    path_msg.poses.push_back(ps);
1615	  }
1616	  plan_pub_->publish(path_msg);
1617	  tracking_mission_id_ = m.id;
1618	
1619	  RCLCPP_INFO(get_logger(), "Dispatched mission: %s (order=%s, type=%s, prio=%d, %s->%s, %zu waypoints)",
1620	              m.id.c_str(), m.order_id.c_str(), m.type.c_str(), m.priority,
1621	              m.pickup_station.c_str(), m.dropoff_station.c_str(), waypoints.size());
1622	
1623	  if (event_pub_ && event_pub_->is_activated()) {
1624	    amr_dispatcher_interfaces::msg::MissionEvent msg;
1625	    msg.stamp = now();
1626	    msg.mission_id = m.id;
1627	    msg.order_id = m.order_id;
1628	    msg.event = "active";
1629	    msg.from_state = "PENDING";
1630	    msg.to_state = "ACTIVE";
1631	    msg.reason = "dispatched by scheduler";
1632	    event_pub_->publish(msg);
1633	  }
1634	}
