1638	  current_pose_.y = msg->pose.pose.position.y;
1639	  current_pose_.yaw = amr_dispatcher_core::path_tracking::YawFromQuaternion(
1640	      msg->pose.pose.orientation.z, msg->pose.pose.orientation.w);
