1644	void DispatcherNode::TrackingErrorCb(
1645	    const amr_dispatcher_interfaces::msg::TrackingError::SharedPtr msg) {
1646	  // action 模式的到达信号归 bridge 消费、结果由 NavResultCb 收口：
1647	  // dispatcher 若自行 CompleteMission 会对同一 NavigateSequence goal 发
1648	  // async_cancel_goal，把已完成 goal 打成 CANCELED（审查 I2）
1649	  if (navigation_backend_ == "action") {
1650	    return;
1651	  }
1652	  // plan 模式下必须按周期喂活 progress：path_tracker_node 以 control_rate_hz
1653	  // 持续发布 /tracking/error，若仅 arrived=true 才刷新时间戳，长距离巡航
1654	  // (>10s) 会触发 DeadlockDetector 的 active_idle_threshold 误判并取消任务
1655	  if (!tracking_mission_id_.empty()) {
1656	    mission_last_progress_[tracking_mission_id_] = std::chrono::steady_clock::now();
1657	  }
1658	  if (!msg->arrived || tracking_mission_id_.empty()) {
1659	    return;
1660	  }
1661	  const std::string finished_id = tracking_mission_id_;
1662	  tracking_mission_id_.clear();
1663	  mission_last_progress_[finished_id] = std::chrono::steady_clock::now();
1664	  CompleteMission(finished_id, "arrived at goal");
1665	}
