1667	void DispatcherNode::CompleteMission(const std::string& mission_id, const std::string& reason) {
1668	  // 单车执行槽位兜底释放：plan 模式由 TrackingErrorCb 先清（幂等）、
1669	  // action 模式由 NavResultCb 收口——此处不清则槽位残留，后续任务永远无法派发（审查 C1）
1670	  if (tracking_mission_id_ == mission_id) {
1671	    tracking_mission_id_.clear();
1672	  }
1673	  std::string order_id;
1674	  {
1675	    std::lock_guard<std::mutex> lock(active_missions_mutex_);
1676	    auto it = active_missions_.find(mission_id);
1677	    if (it == active_missions_.end()) {
1678	      return;
1679	    }
1680	    order_id = it->second.order_id;
1681	    active_missions_.erase(it);
1682	  }
1683	  // ExecuteMission goal 成功收口；action 模式清在途导航 goal（result 到达前的兜底取消）
1684	  FinishExecuteGoal(mission_id, ExecuteFinish::kSucceed, reason, 0);
1685	  mission_dispatch_time_.erase(mission_id);  // plan 模式无 handle 时的派发时刻遗忘
1686	  ForgetMissionDispatchState(mission_id);    // 路由锁记账/等待记录/派发起点遗忘
1687	  if (navigation_backend_ == "action" && pending_nav_mission_id_ == mission_id) {
1688	    if (nav_client_ && pending_nav_goal_handle_) {
1689	      nav_client_->async_cancel_goal(pending_nav_goal_handle_);
1690	    }
1691	    pending_nav_mission_id_.clear();
1692	    pending_nav_goal_handle_.reset();
1693	  }
1694	
1695	  // 结果处理走 mission_result 行为树：成功分支给资源释放与失败计数复位决策
1696	  amr_dispatcher_core::workflow::MissionResultWorkflowInput result_input;
1697	  result_input.code = amr_dispatcher_core::workflow::MissionActionResultCode::kSucceeded;
1698	  result_input.result_success = true;
1699	  result_input.result_message = reason;
1700	  const auto result_bt = amr_dispatcher_bt::TickMissionResultBehaviorTree(result_input);
1701	  RCLCPP_INFO(get_logger(), "Mission %s result via BT: branch=%s state=%s", mission_id.c_str(),
1702	              result_bt.branch.c_str(),
1703	              result_bt.success ? result_bt.decision.state.c_str() : "tree_failed");
1704	
1705	  // 树失败时回退旧行为（无条件释放），防树异常导致资源泄漏
1706	  if (!result_bt.success || result_bt.decision.release_all_resources) {
1707	    if (reservation_table_) {
1708	      reservation_table_->Release(mission_id);
1709	    }
1710	  }
1711	  if (result_bt.success && result_bt.decision.reset_failure_retry_count) {
1712	    mission_attempts_.erase(mission_id);
1713	    mission_last_progress_.erase(mission_id);
1714	  }
1715	  RCLCPP_INFO(get_logger(), "Mission completed: %s (%s)", mission_id.c_str(), reason.c_str());
1716	  if (event_pub_ && event_pub_->is_activated()) {
1717	    amr_dispatcher_interfaces::msg::MissionEvent msg;
1718	    msg.stamp = now();
1719	    msg.mission_id = mission_id;
1720	    msg.order_id = order_id;
1721	    msg.event = "completed";
1722	    msg.from_state = "ACTIVE";
1723	    msg.to_state = "FINISHED";
1724	    msg.reason = reason;
1725	    event_pub_->publish(msg);
1726	  }
1727	  if (event_log_) {
1728	    amr_dispatcher_core::dispatcher::MissionEvent evt;
1729	    evt.stamp = "now";
1730	    evt.mission_id = mission_id;
1731	    evt.event = "completed";
1732	    evt.message = reason;
1733	    event_log_->Append(evt);
1734	  }
1735	  ReArmQueueStartRequest();  // 队列非空时重新武装 runtime 树的启动请求
1736	}
