1738	void DispatcherNode::FailMission(const std::string& mission_id, const std::string& reason) {
1739	  std::string order_id;
1740	  amr_dispatcher_core::dispatcher::Mission mission_copy;
1741	  {
1742	    std::lock_guard<std::mutex> lock(active_missions_mutex_);
1743	    auto it = active_missions_.find(mission_id);
1744	    if (it == active_missions_.end()) {
1745	      return;
1746	    }
1747	    order_id = it->second.order_id;
1748	    mission_copy = it->second;
1749	    active_missions_.erase(it);
1750	  }
1751	  // ExecuteMission goal 失败收口（error_code=1）；action 模式取消在途导航 goal
1752	  FinishExecuteGoal(mission_id, ExecuteFinish::kAbort, reason, 1);
1753	  mission_dispatch_time_.erase(mission_id);  // plan 模式无 handle 时的派发时刻遗忘
1754	  ForgetMissionDispatchState(mission_id);    // 路由锁记账/等待记录/派发起点遗忘
1755	  if (navigation_backend_ == "action" && pending_nav_mission_id_ == mission_id) {
1756	    if (nav_client_ && pending_nav_goal_handle_) {
1757	      nav_client_->async_cancel_goal(pending_nav_goal_handle_);
1758	    }
1759	    pending_nav_mission_id_.clear();
1760	    pending_nav_goal_handle_.reset();
1761	  }
1762	
1763	  // 失败结果先经 mission_result 行为树分类：资源释放决策 + 失败处理标记
1764	  amr_dispatcher_core::workflow::MissionResultWorkflowInput result_input;
1765	  result_input.code = amr_dispatcher_core::workflow::MissionActionResultCode::kFailed;
1766	  result_input.result_success = false;
1767	  result_input.result_message = reason;
1768	  const auto result_bt = amr_dispatcher_bt::TickMissionResultBehaviorTree(result_input);
1769	
1770	  if (!result_bt.success || result_bt.decision.release_all_resources) {
1771	    if (reservation_table_) {
1772	      reservation_table_->Release(mission_id);
1773	    }
1774	  }
1775	  if (tracking_mission_id_ == mission_id) {
1776	    tracking_mission_id_.clear();
1777	    // 发布空路径让 path_tracker 停下
1778	    if (plan_pub_ && plan_pub_->is_activated()) {
1779	      nav_msgs::msg::Path empty;
1780	      empty.header.stamp = now();
1781	      empty.header.frame_id = "map";
1782	      plan_pub_->publish(empty);
1783	    }
1784	  }
1785	  RCLCPP_WARN(get_logger(), "Mission failed: %s (%s)", mission_id.c_str(), reason.c_str());
1786	  if (event_pub_ && event_pub_->is_activated()) {
1787	    amr_dispatcher_interfaces::msg::MissionEvent msg;
1788	    msg.stamp = now();
1789	    msg.mission_id = mission_id;
1790	    msg.order_id = order_id;
1791	    msg.event = "failed";
1792	    msg.from_state = "ACTIVE";
1793	    msg.to_state = "FAILED";
1794	    msg.reason = reason;
1795	    event_pub_->publish(msg);
1796	  }
1797	
1798	  // 恢复策略走 mission_recovery 行为树：retry / dock / manual 三级决策
1799	  const bool handle_failure = !result_bt.success || result_bt.decision.handle_failure;
1800	  std::string recovery_action = "none";
1801	  std::string recovery_message;
1802	  if (handle_failure && queue_) {
1803	    amr_dispatcher_bt::MissionRecoveryBehaviorTreeInput rec_input;
1804	    rec_input.retry_count = mission_attempts_[mission_id];
1805	    rec_input.is_dock_mission = mission_copy.type == "charge";
1806	    rec_input.mission_id = mission_id;
1807	    rec_input.failure_message =
1808	        (result_bt.success && !result_bt.decision.failure_message.empty())
1809	            ? result_bt.decision.failure_message
1810	            : reason;
1811	    rec_input.recovery_priority = mission_copy.priority;
1812	    rec_input.next_queue_sequence = next_sequence_;
1813	    const auto rec_bt = amr_dispatcher_bt::TickMissionRecoveryBehaviorTree(rec_input);
1814	    recovery_action = rec_bt.decision.action;
1815	    recovery_message = rec_bt.decision.message;
1816	    RCLCPP_INFO(get_logger(), "Recovery via BT: branch=%s action=%s recoverable=%d (%s)",
1817	                rec_bt.branch.c_str(), rec_bt.decision.action.c_str(),
1818	                rec_bt.decision.recoverable ? 1 : 0, rec_bt.decision.message.c_str());
1819	
1820	    if (rec_bt.success && rec_bt.decision.action == "retry") {
1821	      auto retry = mission_copy;
1822	      retry.attempt += 1;
1823	      auto push = queue_->Push(retry);
1824	      if (push.accepted) {
1825	        mission_attempts_[mission_id] = rec_input.retry_count + 1;
1826	        queue_start_requested_ = true;
1827	      } else {
1828	        recovery_action = "manual";
1829	        recovery_message = "retry re-enqueue rejected: " + push.message;
1830	      }
1831	    } else if (rec_bt.success && rec_bt.decision.action == "dock") {
1832	      // 回坞：入队一条到充电站点的 charge 任务；站点缺失则降级为仅记录
1833	      const auto& catalog = catalog_reloader_ ? catalog_reloader_->catalog()
1834	                                              : amr_dispatcher_core::catalog::StationCatalog{};
1835	      const auto* dock_st = amr_dispatcher_core::catalog::FindStation(catalog, recovery_dock_station_);
1836	      if (dock_st) {
1837	        amr_dispatcher_core::dispatcher::Mission dock_m;
1838	        StampMissionIdentity(dock_m, next_sequence_);  // B4：id/sequence 同源
1839	        dock_m.order_id = "dock_" + mission_id;
1840	        dock_m.type = "charge";
1841	        dock_m.dropoff_station = recovery_dock_station_;
1842	        dock_m.priority = mission_copy.priority;
1843	        auto push = queue_->Push(dock_m);
1844	        if (push.accepted) {
1845	          queue_start_requested_ = true;
1846	        } else {
1847	          recovery_action = "manual";
1848	          recovery_message = "dock enqueue rejected: " + push.message;
1849	        }
1850	      } else {
1851	        recovery_action = "manual";
1852	        recovery_message = "dock station not found: " + recovery_dock_station_;
1853	      }
1854	    }
1855	
1856	    if (event_pub_ && event_pub_->is_activated()) {
1857	      amr_dispatcher_interfaces::msg::MissionEvent msg;
1858	      msg.stamp = now();
1859	      msg.mission_id = mission_id;
1860	      msg.order_id = order_id;
1861	      msg.event = "recovery";
1862	      msg.from_state = "FAILED";
1863	      msg.to_state = recovery_action == "manual" ? "MANUAL_INTERVENTION" : "RECOVERING";
1864	      msg.reason = recovery_action + ": " + recovery_message;
1865	      event_pub_->publish(msg);
1866	    }
1867	    if (event_log_) {
1868	      amr_dispatcher_core::dispatcher::MissionEvent evt;
1869	      evt.stamp = "now";
1870	      evt.mission_id = mission_id;
1871	      evt.event = "recovery";
1872	      evt.message = recovery_action + ": " + recovery_message;
1873	      event_log_->Append(evt);
1874	    }
1875	  }
1876	  ReArmQueueStartRequest();
1877	}
1878	
1879	amr_dispatcher_core::dispatcher::DeadlockSnapshot DispatcherNode::BuildDeadlockSnapshot() {
1880	  amr_dispatcher_core::dispatcher::DeadlockSnapshot snap;
1881	  // 等待记录只对仍在排队的任务有效：被批量取消/离场的等待者不进 waiting_for
1882	  //（防 WFG 残留幽灵等待者；派发成功/终态路径已即时遗忘，此处兜底清扫）
1883	  if (queue_) {
1884	    for (auto wait = pending_wait_.begin(); wait != pending_wait_.end();) {
1885	      if (queue_->Contains(wait->first)) {
1886	        ++wait;
1887	      } else {
1888	        wait = pending_wait_.erase(wait);
1889	      }
1890	    }
1891	  }
1892	  for (const auto& [id, m] : active_missions_) {
1893	    snap.active_missions.push_back(m);
1894	    snap.last_progress[id] = mission_last_progress_[id];
1895	  }
1896	  // WFG 数据上环：held_by 与预留资源集合来自预约表快照（resource -> owner），
1897	  // waiting_for 来自 Peek 预留失败的排队任务，长持锁取证时刻来自任务预留记账
1898	  //（人工 ReserveResourceCb 不记，避免长持锁误报）
1899	  if (reservation_table_) {
1900	    for (const auto& [resource_id, owner_id] : reservation_table_->Snapshot()) {
1901	      snap.allocation_graph.held_by[resource_id] = owner_id;
1902	      snap.reserved_resource_ids.insert(resource_id);
1903	    }
1904	  }
1905	  snap.allocation_graph.waiting_for = pending_wait_;
1906	  snap.reservation_acquired_at = mission_reserved_at_;
1907	  return snap;
1908	}
1909	
1910	void DispatcherNode::DeadlockTick() {
1911	  if (!deadlock_detector_ || !recovery_policy_) {
1912	    return;
1913	  }
1914	
1915	  const auto snap = BuildDeadlockSnapshot();
1916	
1917	  const auto findings = deadlock_detector_->Detect(snap);
1918	  deadlock_flag_ = !findings.empty();
1919	
1920	  // 拓扑状态投影的死锁输入：存各 finding 的环路径，无死锁时清空
1921	  last_deadlock_findings_.clear();
1922	  for (const auto& finding : findings) {
1923	    if (!finding.cycle_path.empty()) {
1924	      last_deadlock_findings_.push_back(finding.cycle_path);
1925	    }
1926	  }
1927	
1928	  if (deadlock_flag_) {
1929	    RCLCPP_WARN(get_logger(), "Deadlock findings count: %zu", findings.size());
1930	    auto actions = recovery_policy_->Decide(
1931	        findings, [this](const std::string& mid) {
1932	          auto it = mission_attempts_.find(mid);
1933	          return it != mission_attempts_.end() ? it->second : 0;
1934	        });
1935	
1936	    for (const auto& act : actions) {
1937	      RCLCPP_WARN(get_logger(), "Recovery action on %s: reason=%s",
1938	                  act.mission_id.c_str(), act.reason.c_str());
1939	      if (act.kind == amr_dispatcher_core::dispatcher::RecoveryAction::Kind::kPause) {
1940	        queue_->PauseOrder(act.mission_id);
1941	      } else if (act.kind == amr_dispatcher_core::dispatcher::RecoveryAction::Kind::kCancel) {
1942	        // 取消也走结果树：canceled 分支给资源释放决策，同时补发可观测事件
1943	        std::string canceled_order_id;
1944	        auto cancel_it = active_missions_.find(act.mission_id);
1945	        if (cancel_it != active_missions_.end()) {
1946	          canceled_order_id = cancel_it->second.order_id;
1947	        }
1948	        amr_dispatcher_core::workflow::MissionResultWorkflowInput cancel_input;
1949	        cancel_input.code = amr_dispatcher_core::workflow::MissionActionResultCode::kCanceled;
1950	        cancel_input.result_message = act.reason;
1951	        const auto cancel_bt = amr_dispatcher_bt::TickMissionResultBehaviorTree(cancel_input);
1952	        active_missions_.erase(act.mission_id);
1953	        if (!cancel_bt.success || cancel_bt.decision.release_all_resources) {
1954	          if (reservation_table_) {
1955	            reservation_table_->Release(act.mission_id);
1956	          }
1957	        }
1958	        // 死锁恢复取消的级联：清在途 NavigateSequence goal + 终结 ExecuteMission goal
1959	        if (navigation_backend_ == "action" && pending_nav_mission_id_ == act.mission_id) {
1960	          if (nav_client_ && pending_nav_goal_handle_) {
1961	            nav_client_->async_cancel_goal(pending_nav_goal_handle_);
1962	          }
1963	          pending_nav_mission_id_.clear();
1964	          pending_nav_goal_handle_.reset();
1965	        }
1966	        FinishExecuteGoal(act.mission_id, ExecuteFinish::kAbort, act.reason, 1);
1967	        mission_dispatch_time_.erase(act.mission_id);  // plan 模式无 handle 时的派发时刻遗忘
1968	        ForgetMissionDispatchState(act.mission_id);    // 路由锁记账/等待记录/派发起点遗忘
1969	        // 死锁恢复取消到正在跟踪 /plan 的任务时，必须释放跟踪槽位并停车，
1970	        // 否则 tracking_mission_id_ 悬挂导致后续任务永远无法下发。
1971	        if (tracking_mission_id_ == act.mission_id) {
1972	          tracking_mission_id_.clear();
1973	          if (plan_pub_ && plan_pub_->is_activated()) {
1974	            nav_msgs::msg::Path empty;
1975	            empty.header.stamp = now();
1976	            empty.header.frame_id = "map";
1977	            plan_pub_->publish(empty);
1978	          }
1979	        }
1980	        if (event_pub_ && event_pub_->is_activated()) {
1981	          amr_dispatcher_interfaces::msg::MissionEvent msg;
1982	          msg.stamp = now();
1983	          msg.mission_id = act.mission_id;
1984	          msg.order_id = canceled_order_id;
1985	          msg.event = "canceled";
1986	          msg.to_state = "CANCELED";
1987	          msg.reason = act.reason;
1988	          event_pub_->publish(msg);
1989	        }
1990	        RCLCPP_WARN(get_logger(), "Deadlock cancel via BT: branch=%s state=%s reason=%s",
1991	                    cancel_bt.branch.c_str(),
1992	                    cancel_bt.success ? cancel_bt.decision.state.c_str() : "tree_failed",
1993	                    act.reason.c_str());
1994	        ReArmQueueStartRequest();
1995	      } else if (act.kind == amr_dispatcher_core::dispatcher::RecoveryAction::Kind::kRetry) {
1996	        // B8：写 map 前先确认任务仍在册（active 或排队中）——
1997	        // 死锁恢复决策基于快照延迟生成，目标可能已终态/被操作员移除，
1998	        // 盲区写 map 会把幽灵 mission_id 驻留在 attempts/last_progress 里。
1999	        const bool mission_known =
2000	            active_missions_.count(act.mission_id) > 0 ||
2001	            (queue_ && queue_->Contains(act.mission_id));
2002	        if (mission_known) {
2003	          mission_attempts_[act.mission_id]++;
2004	          mission_last_progress_[act.mission_id] = std::chrono::steady_clock::now();
2005	        } else {
2006	          RCLCPP_INFO(get_logger(),
2007	                      "Deadlock kRetry skipped for unknown mission %s (no longer active/queued)",
2008	                      act.mission_id.c_str());
2009	        }
2010	      }
2011	    }
2012	  }
2013	}
2014	
2015	void DispatcherNode::ReArmQueueStartRequest() {
2016	  // 结果/取消/恢复后重新武装 runtime 行为树的启动请求：
2017	  // 队列非空则置位（auto_start_queue 语义），队列清空则复位。
2018	  const auto decision = amr_dispatcher_core::workflow::PlanMissionPostResultQueue(
2019	      amr_dispatcher_core::workflow::MissionPostResultQueueRequest{
2020	          /*existing_queue_start_requested=*/queue_start_requested_,
2021	          /*auto_start_queue=*/true,
2022	          /*queue_running=*/true,
2023	          /*mission_queue_empty=*/queue_ == nullptr || queue_->empty()});
2024	  queue_start_requested_ = decision.queue_start_requested;
2025	}
2026	
2027	void DispatcherNode::PublishState() {
2028	  if (!state_pub_ || !state_pub_->is_activated()) {
2029	    return;
2030	  }
2031	
2032	  amr_dispatcher_interfaces::msg::DispatcherState msg;
2033	  msg.header.stamp = now();
2034	  msg.current_comparator = queue_ ? queue_->comparator_name() : "none";
2035	  msg.queue_size = queue_ ? static_cast<uint32_t>(queue_->size()) : 0;
2036	  msg.queue_capacity = queue_ ? static_cast<uint32_t>(queue_->capacity()) : 0;
2037	  msg.active_missions_count = static_cast<uint32_t>(active_missions_.size());
2038	  msg.deadlock_detected = deadlock_flag_;
2039	
2040	  for (const auto& [id, _] : active_missions_) {
2041	    msg.active_mission_ids.push_back(id);
2042	  }
2043	  if (!msg.active_mission_ids.empty()) {
2044	    msg.active_mission_id = msg.active_mission_ids.front();
2045	  }
2046	
2047	  // ExecuteMission 进度反馈：按派发起点的直线距离折算 percent_complete
2048	  //（state_code=1 WAITING_LOCK 为计划定死的周期反馈语义；导航中的高频反馈由 NavFeedbackCb 发 state_code=2）
2049	  for (const auto& [id, handle] : execute_goal_handles_) {
2050	    if (!handle || !handle->is_executing()) {
2051	      continue;
2052	    }
2053	    auto ait = active_missions_.find(id);
2054	    if (ait == active_missions_.end()) {
2055	      continue;  // 任务已终态（finish 时会查表移除 handle）
2056	    }
2057	    double percent = 0.0;
2058	    auto sit = mission_dispatch_start_.find(id);
2059	    const bool catalog_loaded = catalog_reloader_ != nullptr && catalog_reloader_->loaded();
2060	    if (sit != mission_dispatch_start_.end() && has_odom_ && catalog_loaded &&
2061	        !ait->second.dropoff_station.empty()) {
2062	      const auto* to_st = amr_dispatcher_core::catalog::FindStation(
2063	          catalog_reloader_->catalog(), ait->second.dropoff_station);
2064	      if (to_st) {
2065	        const double total = std::hypot(to_st->x - sit->second.x, to_st->y - sit->second.y);
2066	        const double covered =
2067	            std::hypot(current_pose_.x - sit->second.x, current_pose_.y - sit->second.y);
2068	        if (total > 1e-6) {
2069	          percent = std::min(100.0, 100.0 * covered / total);
2070	        }
2071	      }
2072	    }
2073	    auto fb = std::make_shared<ExecuteMission::Feedback>();
2074	    fb->state_code = 1;  // WAITING_LOCK（计划定死的周期反馈状态）
2075	    fb->current_node = ait->second.dropoff_station;
2076	    fb->percent_complete = static_cast<float>(percent);
2077	    fb->estimated_remaining_sec = 0.0;
2078	    handle->publish_feedback(fb);
2079	  }
2080	
2081	  state_pub_->publish(msg);
2082	
2083	  // /dispatcher/topology_state：safety_gate 与 visualizer 的死锁/锁边输入
2084	  //（快照全量透传，active 仅任务持有的 route_edge，deadlocked_nodes 解析成站点 id）
2085	  if (topology_pub_ && topology_pub_->is_activated()) {
2086	    std::unordered_set<std::string> active_ids;
2087	    for (const auto& [id, _] : active_missions_) {
2088	      active_ids.insert(id);
2089	    }
2090	    const std::vector<std::pair<std::string, std::string>> snapshot =
2091	        reservation_table_ ? reservation_table_->Snapshot()
2092	                           : std::vector<std::pair<std::string, std::string>>{};
2093	    const auto topology = amr_dispatcher_core::dispatcher::BuildTopologyProjection(
2094	        snapshot, active_ids, last_deadlock_findings_);
2095	    amr_dispatcher_interfaces::msg::TopologyState topology_msg;
2096	    topology_msg.stamp = now();
2097	    topology_msg.active_edges = topology.active_edges;
2098	    topology_msg.locked_edges = topology.locked_edges;
2099	    topology_msg.edge_owners = topology.edge_owners;
2100	    topology_msg.deadlocked_nodes = topology.deadlocked_nodes;
2101	    topology_msg.deadlock_detected = topology.deadlock_detected;
2102	    topology_pub_->publish(topology_msg);
2103	  }
2104	}
2105	
2106	}  // namespace amr_dispatcher_ros
2107	
2108	int main(int argc, char* argv[]) {
2109	  rclcpp::init(argc, argv);
2110	  auto node = std::make_shared<amr_dispatcher_ros::DispatcherNode>();
2111	  rclcpp::spin(node->get_node_base_interface());
2112	  rclcpp::shutdown();
2113	  return 0;
2114	}
