241	    return;
242	  }
243	  if (!nav2_client_ || !nav2_client_->action_server_is_ready()) {
244	    // 单点失败 -> 整 goal abort
245	    failed_waypoints_++;
246	    auto result = std::make_shared<NavigateSequence::Result>();
247	    result->success = false;
248	    result->message = "nav2 action server not available: " + nav2_action_name_;
249	    result->completed_waypoints = completed_waypoints_;
250	    result->failed_waypoints = failed_waypoints_;
251	    RCLCPP_ERROR(get_logger(), "%s (waypoint %zu/%zu)", result->message.c_str(),
252	                 current_index_ + 1, nav_poses_.size());
253	    StopFallbackMotion();  // 终结路径统一停车（use_nav2_ 下为空操作）
254	    current_goal_->abort(result);
255	    current_goal_.reset();
256	    waiting_arrival_ = false;
257	    nav2_pending_ = false;
258	    return;
