266	
267	  rclcpp_action::Client<nav2_msgs::action::NavigateToPose>::SendGoalOptions opts;
268	  opts.feedback_callback =
269	      [this, seq_goal](const rclcpp_action::ClientGoalHandle<nav2_msgs::action::NavigateToPose>::SharedPtr& gh,
270	                       const std::shared_ptr<const nav2_msgs::action::NavigateToPose::Feedback>& fb) {
271	        Nav2FeedbackCb(gh, fb, seq_goal);
272	      };
273	  opts.result_callback =
274	      [this, seq_goal](const rclcpp_action::ClientGoalHandle<nav2_msgs::action::NavigateToPose>::WrappedResult& result) {
275	        Nav2ResultCb(result, seq_goal);
276	      };
277	  nav2_client_->async_send_goal(nav_goal, opts);
278	  PublishSeqFeedback("NAVIGATING", 0.0);
