285	    const std::shared_ptr<const nav2_msgs::action::NavigateToPose::Feedback>& fb,
286	    const std::weak_ptr<GoalHandleNavSeq>& seq_goal) {
287	  // 身份校验：只处理仍属于当前 NavigateSequence goal 的在途反馈
288	  const auto locked = seq_goal.lock();
289	  if (!locked || locked != current_goal_ || !nav2_pending_) {
290	    return;
291	  }
