297	    const std::weak_ptr<GoalHandleNavSeq>& seq_goal) {
298	  const auto locked = seq_goal.lock();
299	  if (!locked || locked != current_goal_ || !nav2_pending_) {
300	    return;  // 已被 cancel 终结 / 已换 goal：丢弃过期结果
301	  }
302	  nav2_pending_ = false;
303	  if (result.code == rclcpp_action::ResultCode::SUCCEEDED && result.result &&
304	      result.result->error_code == 0) {
305	    PublishSeqFeedback("AT_STATION", 0.0);
306	    AdvanceAfterArrival();
307	    return;
308	  }
309	  // 单点失败 -> 整 goal abort
310	  failed_waypoints_++;
