  // 长度也可能相同，但折线不同，必须作为平行边同时保留。
  {
    std::vector<PixelEdge> unique_edges;
    for (const auto& e : pixel_edges) {
      bool dup = false;
      for (const auto& u : unique_edges) {
        if (e.from == u.from && e.to == u.to &&
            e.polyline_px == u.polyline_px) {
          dup = true;
          break;
        }
        // 反向同边（A->B 与 B->A）：折线反向逐点相等才是同一条几何链。
